export default [{"id":520,"question":"ما في ضرر على المرأة كونها أن تأخذ واحدًا بحفظه لكتاب الله بدون مهر؟","title":"ما حكم الزواج مقابل حفظ القرآن؟","answer":"الجواب: إذا رضيت أزين لها من خاتم من حديد، يعلمها سورة من القرآن أو آية من القرآن؛ نعمة عظيمة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6350/ما-حكم-الزواج-مقابل-حفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/maram085.mp3","categories":["الصداق"]},{"id":523,"question":"حكم الصداق هل هو واجب؟","title":"هل الصداق واجب في النكاح؟","answer":"الجواب: لا ما هو بشرط، لو تزوجها بدون مهر صح النكاح، ويكون لها مهر المثل.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6353/هل-الصداق-واجب-في-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/maram088 - 04 - .mp3","categories":["الصداق"]},{"id":541,"question":"للزوج نصف المهر لو عقد عليها ولم يدخل عليها؟","title":"ماذا يُستحق للزوجة التي تطلق قبل الدخول؟","answer":"الجواب: على القاعدة الشرعية: نصف المهر وَإِنْ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ[البقرة:237].\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6372/ماذا-يستحق-للزوجة-التي-تطلق-قبل-الدخول","audio":"https://files.zadapps.info/binbaz.org.sa/maram107 - 04 - .mp3","categories":["الصداق"]},{"id":770,"question":"لقد انتشر لدى كثيرٍ من الآباء أكلُ مهور بناتهم، مستدلّين لذلك بقوله ﷺ: أنت ومالك لأبيك، فما رأي سماحتكم؟ وهل للأب الأخذ من مال ابنه متى شاء وكيف شاء؟","title":"ما حكم أخذ الآباء مهور بناتهم؟","answer":"الجواب: ثبت عن رسول الله ﷺ أنه قال لمن جاء إليه وقال: إن أبي اجتاح مالي، قال: أنت ومالك لأبيك، وجاء أيضًا عنه ﷺ أنه قال: إنَّ أطيب ما أخذتُم من كسبِكم، وإنَّ أولادكم من كسبِكم.\nفللوالد أن يأخذ من مال ولده ما لا يضرُّه ولا يحتاجه، ومن مال بنته كذلك؛ لقوله ﷺ: لا ضرر ولا ضرار، أما ما يضرُّه يُمنع، فإذا أخذ من ماله أو من مهرها شيئًا يحتاجه الوالدُ ولا يضرُّها ولا يضرُّ ولده الذكر فلا بأس بذلك، الولد بَضْعَة من أبيه، فللوالد أن يأخذ من ماله ما يحتاجه الوالد لنفقته وأهله إذا كان عاجزًا، وله أن يأخذ من ماله زيادةً على ما عنده إذا كان لا يضرُّ الولد؛ لكثرة مال الولد، وله أن يأخذ من مال البنت ما لا يضرُّها أيضًا، إذا كان مالها كثيرًا ولا يضرُّها إذا أخذ منه شيئًا، أما إن كان يضرُّها؛ لأنَّ المهر قليل والحاجات كثيرة؛ فلا يأخذ منه شيئًا، بل يدعه لها حتى تُصلح به شأنها، والله المستعان.","link":"https://binbaz.org.sa/fatwas/20696/ما-حكم-اخذ-الاباء-مهور-بناتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0593ما حكم أخذ المهور من بناتهم مستدلين بقول النبي صلى الله عليه وسلم أنت ومالك لأبيك؟ ابن باز.mp3","categories":["الصداق"]},{"id":3652,"question":"ما اشتهر أن أم سليم جعلت إسلام أبي طلحة هو مهرها؟","title":"حكم جعل إسلام الرجل أو تعليم القرآن مهرًا","answer":"الجواب: هذا يرى بعض أهل العلم جعل إسلام الرجل أو تعليم القرآن مهرًا لا بأس به، ولكن نزول الآية بعد ذلك، آية النساء وهي مدنية أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] يدل على أنه لا بدّ من المال، ولعل قصة أم سليم قبل نزول الآية، الواجب فرض المال ولو قليل أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24].","link":"https://binbaz.org.sa/fatwas/23840/حكم-جعل-اسلام-الرجل-او-تعليم-القران-مهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أم سليم جعلت إسلام أبي طلحة هو مهرها.mp3","categories":["الصداق"]},{"id":3663,"question":"هل لولي الأمر أن يحدد المهر؟","title":"هل لولي الأمر أن يحدد المهر؟","answer":"الجواب: التحديد ما عليه دليل.","link":"https://binbaz.org.sa/fatwas/23851/هل-لولي-الامر-ان-يحدد-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للولي أن يحدد المهر.mp3","categories":["الصداق"]},{"id":4808,"question":"الصور والحالات التي للزوج أن يرجع على زوجته بعقدٍ جديدٍ هل لا بدّ من مهرٍ؟","title":"حكم المهر إذا رجع الزوج إلى زوجته بعقدٍ جديدٍ","answer":"نعم، لا بدّ من عقدٍ جديدٍ، ولو كان في عقد جديد لا بدّ من مهرٍ، ولو قليل، لا نكاحَ إلا بمهرٍ، ولو قليل: أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24].","link":"https://binbaz.org.sa/fatwas/25203/حكم-المهر-اذا-رجع-الزوج-الى-زوجته-بعقد-جديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لا بد من المهر إذا رجع الزوج على زوجته بعقدٍ جديدٍ.mp3","categories":["الصداق"]},{"id":6174,"question":"هل يجوز للوالد أن يأكل مهر ابنته، ولا يعطيها منه شيئًا؟","title":"حكم أخذ الوالد مهر ابنته دون رضاها","answer":"الجواب: الوالد يجب عليه أن ينظر في الأمر، وليس له أن يضرها، ولا يحرم عليه أن يأكل من مال ولده؛ النبي -عليه الصلاة والسلام- جاءه رجل يشتكي إليه، قال: إن أبي اجتاح مالي؟! قال: أنت ومالك لأبيك وفي حديث عائشة -رضي الله عنها- أن النبي ﷺ قال: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم.  والصحيح من أقوال العلماء: أنه لا بأس أن يأخذ الوالد من مال ولده الذكر، والأنثى ما ينفعه من دون ضرر الابن، ولا بالبنت، هذا هو الصواب، فليس له أن يضر ولده، ولا أن يضر بنته، لكن إذا أخذ شيئًا ينفعه، ولا يحصل به ضررًا على ولد، ولا على بنت، فهذا لا حرج في ذلك. وإذا تنازعا فالمحكمة تنظر في أمرهم، إذا تنازع الولد مع والده، فيحلها الحاكم، ولكن الأولى بالولد أن لا يخاصم أباه، وأن يعطيه ما يرضيه، وهكذا البنت ينبغي أن لا تخاصم أباها، بل تعطيه ما يسامح نفسه، ويرضيه عنها، وتبقي ما ينفعه فإن الوالد له شأن، وله حق كبير فلا ينبغي للذكر، ولا للأنثى أن يتنازعا معه، ولا أن يخاصماه؛ بل ينبغي أن يرضيه بما تيسر من المهر، ومن غير المهر.  والوالد لا يجب عليه أن يكون جشعًا يضر أولاده، ويضر بناته لا، بل الواجب عليه أن يخاف الله، وأن يراقب الله، وأن يكون ذا أخلاق فاضلة، وذا عفة، وذا عطف، وحنو على أولاده، فتعطى من مهرها ما يقوم بحالها، وما تتجمل به لزوجها، ويعطى من مهرها ما يسد حاجته، أو ما يرضيه من ذلك الشيء من دون مضرة على البنت.  وهكذا الولد إذا كان له أسباب إن كان عنده سعة أعطى والده، وإن كان ما عنده سعة راتبه بقدر حاجة بيته فليس للوالد أن يأخذ منه شيئًا، بل يحرم على والده أن يضره بذلك، أما إذا كان الولد عنده سعة، وعنده زيادة تفضل عن حاجته؛ فإنه ينبغي له أن يعطي والده ما يرضيه من هذا الزائد، ولا يكون بينه وبين والده نزاع.","link":"https://binbaz.org.sa/fatwas/1627/حكم-اخذ-الوالد-مهر-ابنته-دون-رضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_518.mp3","categories":["الصداق","قضايا المرأة"]},{"id":6175,"question":"هل لولي البنت أن يأخذ من مهر البنت؟","title":"حكم أخذ الأب من مهر ابنته","answer":"الجواب: الأب له أن يأخذ ما لا يضرها، النبي -عليه الصلاة والسلام- قال: أنت ومالك لأبيك وقال: إن أولادكم من كسبكم، وإن أطيب ما أكلتم من كسبكم فله أن يأخذ من المهر، ومن مال ولده، ولا يضر الولد.","link":"https://binbaz.org.sa/fatwas/1633/حكم-اخذ-الاب-من-مهر-ابنته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_524.mp3","categories":["الصداق","قضايا المرأة"]},{"id":6408,"question":"ما الحكم إذا دفعت المرأة الثرية مهرها للرجل؟","title":"حكم دفع المرأة مهرها لزوجها","answer":"الجواب: ما في بأس، إذا أعطته لا بأس، لكن لا بدّ منه شيء، ولو قليل، لا بدّ أن يعطيها شيئًا؛ لأن الله قال: أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] فإذا أعطته شيئًا مما تقضى به الحاجة، فرشت البيت، وأعطته ما يصنع به الوليمة؛ فجزاها الله خيرًا، هذا طيب، في الهند، وباكستان، وبلاد أخرى؛ المرأة هي التي تدفع عن الزوج، فإذا دفعت المرأة عن الزوج؛ فلا بأس، لكن لا بدّ من شيء منه، لا بدّ أن يعطيها مثلاً عشرة، مائة، ألف، لا بدّ يعطيها شيئًا؛ حتى يصدق عليه أنه ابتغاها بماله أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] فلا بدّ أن يكون مهرٌ منه، ولو قليل، يعقد عليه النكاح، والباقي تنفقه هي، وهي مأجورة في هذا، ولا بأس. وهنا أمر آخر نسيت التنبيه عليه، ولا نبه عليه أيضاً المشايخ فيما أذكر، وهي مسألة الخطبة، لا بأس أن يخطب الرجل لبنته، يدور الطيب، يقول: يا فلان أنا أرغب أن أزوجك بنتي، أو أختي مثل ما أن الرجل يخطب البنت، ولي المرأة يخطب أيضاً يلتمس، قد فعل هذا بعض الصحابة، فعله عمر، وفعله غيره. فالمقصود: أن كون الإنسان يلتمس لأخته، أو بنته الشاب الصالح، والرجل الصالح، ويقول: يا فلان أنا ما لي طمع في المال، أزوجك ولو بالقليل، أنا عندي بنت، أو عندي أخت أرغب أن أزوجك، وإذا كنت تحب أن تنظر إليها فليس عندي مانع، فإذا رضيت زوجه إياها بالمهر القليل، وهذا مما يعين على إيجاد الزواج، وعلى عدم الكلفة.    السؤال: يعيروني الجماعة؟  الجواب: ما يهمونك، إذا رضي الله عنك؛ فلا يهمونك.","link":"https://binbaz.org.sa/fatwas/2124/حكم-دفع-المراة-مهرها-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_772.mp3","categories":["الصداق","قضايا المرأة"]},{"id":6716,"question":"هل يجوز لولي البنت أن يأخذ من مهر ابنته شيئًا من المال وهي لا تعلم؟","title":"حكم أخذ الأب من مهر ابنته دون علمها","answer":"الجواب:   يجوز لأبيها أن يأخذ من مالها ما لا يضرها، لقوله ﷺ: إن أطيب ما أخذتم من كسبكم، وإن أولادكم من كسبكم فلأبيها أن يأخذ من مالها ما يرى من دون ضرر عليها، فيدع لها ما تحتاج إليه، ويأخذ منه ما ينفعه، ولا يضرها، لا بأس، أما غيره فلا إلا بإذنها إذا كانت رشيدة.","link":"https://binbaz.org.sa/fatwas/2588/حكم-اخذ-الاب-من-مهر-ابنته-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1084.mp3","categories":["الصداق","الآداب والأخلاق"]},{"id":7473,"question":"أيضاً يقول: هناك بعض الآباء يتجاوزون في المهور، نريد أن توجهوا لهم النصيحة لعل الله  أن يهديهم في ذلك.","title":"حكم المغالاة في المهور والولائم","answer":"الجواب: هذا أمر عام ومصيبة كبيرة، وهي المغالاة في المهور، ونصيحتي لكل مسلم أن يدع ذلك، وأن يحذر المغالاة في مهر بنته أو أخته أو قريبته الأخرى، وأن يتساهل في ذلك ويرضى بالمهر المناسب الذي يعين المرأة على حاجاتها المعروفة، ولا يكون فيه إرهاق للزوج ولا منع للنكاح، هذه الكل يشكو منها، مسألة المغالاة في المهور، والمغالاة أيضاً في الولائم، كلتاهما ضارتان، فينبغي للأولياء وللنساء أيضاً أن لا يشددوا في ذلك بأن ترضى المرأة وأمها وقراباتها بالشيء المناسب، كما يرضى الأب وبقية الأولياء بذلك، بعض الأحيان قد يكون الأب يرضى أو الولي لكن لا ترضى أمها وأختها ونحو ذلك، وربما حملته أمها على المغالاة.\nفالحاصل: أن هذا مطلوب من الجميع؛ مطلوب من الأم والخالة والبنت نفسها، مطلوب من الأب، مطلوب من الإخوة، مطلوب من الأجداد، كلهم يتعاونون في تسهيل المهور وعدم المغالاة حتى يتيسر تزويج قريباتهن. أما مع المغالاة فإن البنت تبقى حبيسة البيت ولا يتقدم لها إلا القليل من الناس، ليس كل واحد عنده القوة على المهر المرتفع، ثم هذا لا ينبغي لأن المغالاة في المهور تفضي إلى فساد كبير، إلى تعطيل البنات والأخوات، وتعطيل الشباب، والوقوع في الفواحش، هذا كله شره عظيم وعاقبته وخيمة. كذلك الولائم ينبغي ألا يعني يتنافس فيها، بدل ما يذبح عشر ذبائح خمسة عشر يكتفي بواحدة أو ثنتين أوثلاث، بدل ما يدعو مائة مائتين يدعو خمسة، عشرة من أقاربه الأدنين ويكتفي بذلك حتى تكون النفقة أقل، وحتى يستطيع أن يتقدم للزواج، لكن إذا ذكر أن هناك ولائم تحتاج إلى ألوف بل عشرات الألوف مع مغالاة المهر، فإن هذا كله يسبب تعطيل الرجل وتعطيل البنت جميعاً، ولا حول ولا قوة إلا بالله، نسأل الله للجميع الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/4316/حكم-المغالاة-في-المهور-والولاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_003/00303.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":7551,"question":"في الحقيقة هناك من يتساءل أيضاً يقول: ما المراد بصداق المرأة، هل هو الأشياء التي يشترى منها مثلاً حلي وتجهيز من أواني وملابس وغيره، أم أن الصداق يسلم في يدها ويشترى الحلي وخلافه من نقود أخرى؟","title":"المعتبر في صداق المرأة","answer":"الجواب: الصداق يتنوع، كل ما يدفع لها في مقابل استحلال فرجها هو المهر، كل شيء يدفع لها يشرط على الزوج في مقابل عقد النكاح فهو مهرها، سواء كان نقوداً، أو حلياً، أو فرشاً .. أو غير ذلك، كل ما يدفع لها من المال سواء كان نقداً أو غيره فهو يعتبر مهر، إذا كان شرطاً في النكاح، أما إذا كان بعد النكاح فهذا من باب التورع، من باب المساعدة، ما كان شرطاً في النكاح يتفقان عليه في موافقتها ورضاها بالعقد فهذا هو المهر، ولا يختص بالنقود، بل يدخل فيه ما يشرط من غير النقود، مثل الملابس، مثل الحلي؛ مثل الذهب أو الفضة.. أو غير ذلك، مثل ما يسمونه الآن: غرفة النوم.. إلى غير ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4538/المعتبر-في-صداق-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_013/01302.mp3","categories":["الصداق"]},{"id":7628,"question":"هذه الرسالة من إحدى السائلات تقول في رسالتها: أختكم في الإسلام (ع. م. ز)، أشكر العاملين على هذا البرنامج والمجيبين على أسئلة المستمعين، وأحيطكم علماً بأني امرأة تزوجت ثم طلقني زوجي وأعطاني مهري جنيهات ذهب، فأخذه أبوي عندي، وبعد ذلك طلبته فيه، فيقول لي: لا أعطيك هذا المهر، ثم ترددت عليه، وأخيراً قال لي: لا أعطيك إياه حتى الموت، والسؤال عن هذا هو: هل تجب عليه زكاة علماً هو ليس عني؟","title":"حكم أخذ الأب مهر ابنته أو مالها","answer":"الجواب: ما دام أخذه والدها فالوالد يملك أخذه إذا كانت بالمستغني عنه، أو كان يقوم بنفقتها، فالمال الذي أخذه والدها لا حرج فيه، والمال ماله حينئذ؛ لأن الرسول عليه السلام قال أنت ومالك لأبيك وقال عليه الصلاة والسلام: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فللوالد أن يأخذ من البنت أو من الذكر الذي هو ولده، له أن يأخذ من ماله ما لا يضره، فإذا أخذ من مال بنته ما لا يضرها، أو من مال ابنه ما لا يضره فلا حرج في ذلك على الصحيح، وإذا كانت هذه البنت يضرها هذا الذهب وهي في ضرورة إليه، ففي إمكانها أن ترفع الأمر للمحكمة، والمحكمة تنظر في ذلك، أما إن كانت لا يضرها ذلك؛ لأنها غنية عنه أو لأن والدها يقوم بحالها وينفق عليها، أو لأن زوجها يقوم بحالها، ولا تحتاج لهذا المال فإن والدها لا حرج عليه في ذلك، والأولى بها ألا تخاصم، إن تيسر ذلك من دون مخاصمة فهذا هو الأولى بالسائلة، وإن كانت هناك حاجة للخصومة فالأولى ترك ذلك؛ لأن والدها له حق عظيم، وبره واجب، وقد يكون محتاجاً لهذا المال، وهي إذا كانت مستغنية عنه أو يمكن أن تستغني عنه فهذا أولى لها وخير لها ألا تخاصم. \nالمقدم: أيضاً هي تقول: هل يجوز لي أن أغضب والدي وأخذ المال بالقوة أم لا، وقد تفضلتم بالإجابة على هذا.","link":"https://binbaz.org.sa/fatwas/4682/حكم-اخذ-الاب-مهر-ابنته-او-مالها ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_025/02504.mp3","categories":["الصداق"]},{"id":7862,"question":"هذه أول رسالة التي بين يدينا وردتنا من أحمد بن محمد اليحيى، يقول أحمد بن محمد بن يحيى في رسالته هذه:السلام عليكم ورحمة الله وبركاته، وبعد:بعد أن شكر أصحاب الفضيلة الذين يجيبون على أسئلة واستفسارات المستمعين ويرجو من تمديد البرنامج، يقول: الذي توفي عنها زوجها ولم يفرض لها زوجها مهراً ولم يدخل بها، فهل لها مهر المثل أو نصف مهر المثل أم المتعة وفقكم الله؟","title":"حكم من توفي زوجها قبل الدخول بها ولم يحدد مهراً","answer":"الجواب: الذي مات عنها زوجها ولم يعين لها مهراً ولم يدخل بها لها مهر المثل، كما ثبت هذا عن النبي ﷺ فإنه ثبت عنه أنه سئل عن مثل هذه المسألة فأفتى بأن لها مهر نسائها لا وكس ولا شطط وعليها العدة ولها الميراث ثبت هذا من حديث معقل بن يسار.\nالمقصود: من حديث معقل بن يسار الأشجعي، في امرأة يقال لها ..... بروع بنت واشق توفي عنها زوجها ولم يفرض لها مهراً ولم يدخل بها فقضى النبي فيها عليه الصلاة والسلام بأنها تعطى مهر نسائها لا وكس ولا شطط وعليها العدة ولها الميراث. نعم.","link":"https://binbaz.org.sa/fatwas/5274/حكم-من-توفي-زوجها-قبل-الدخول-بها-ولم-يحدد-مهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05602.mp3","categories":["الصداق"]},{"id":8258,"question":"رسالة وصلت إلى البرنامج من سوريا حلب، ووقع عليها اثنان من الإخوة من هناك : حسين الأسعد وفتحي الحسين، يسألان عن المهر يقولان: عندنا المهر مائة وخمسين ليرة سورية، وأغلب الرجال لا يوجد عندهم نصف هذا المهر، والأب يأخذ المهر من ابنته إجباري، هل هذا حرام أم حلال؟","title":"الحث على تيسير المهور وعدم استيلاء الآباء عليها","answer":"الجواب: يجب على الآباء وعلى جميع الأولياء أن يتقوا الله وأن يحرصوا على تزويج بناتهم بما يسر الله من المهر، وليس لهم أن يشددوا في ذلك، بل عليهم أن يقبلوا القليل إذا رضيت به البنت، فإن تزويجها ولو بالقليل خير من بقائها، ولا يجوز لهم الاعتراض عليها إذا سمحت، ولا أكل صداقها بغير حق وهي في حاجة إليه، إنما يجوز للأب أخذ الفضل، أما الحاجة التي تحتاجها البنت فهي مقدمة وليس لبقية الأولياء أن يأخذوا منه شيئاً إلا بإذنها إذا كانت رشيدة.\nفالمقصود من هذا أن الواجب على الآباء وعلى جميع الأولياء النظر في مصلحة البنات، والعناية بتزويجهن ولو بالمهر القليل، ولو بدرهم واحد، ولو بدرهمين، المقصود عفتها وسلامتها والحرص على ستر عرضها مع ما يسر الله في ذلك من الخير العظيم، والتسبب في وجود الذرية وعفة الرجال والنساء جميعاً.\nفالواجب على الأولياء أن يساعدوا في هذا، وألا يهلكهم الطمع في المال حتى يمنعوا مولياتهم من الزواج، كل هذا خطر عظيم.\nوهذه نصيحتي لجميع الأولياء في أي مكان، في المملكة العربية السعودية أو في حلب أو في أي مكان من أرض الله نصيحتي لهم جميعاً أن يتقوا الله، وأن يزوجوا بناتهم وأخواتهم ومولياتهم بما يسر الله من المهر ولو كان قليلاً، وأن يحرصوا على الطيب صاحب الدين.\nونصيحتي أيضاً للبنات وجميع النساء أن يرضين بالقليل في سبيل العفة واختيار الزوج الصالح ولا يهمهم المال فالمال أمره سهل، إذا يسر الله الزواج جاء المال.\nفينبغي للمؤمن أن يحذر ما حرم الله عليه وأن يحرص على ما شرع الله له، كما قال : وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] فبين سبحانه أن النكاح من أسباب الغنى.\nوفي الحديث عنه صلى الله عليه وسلم أنه قال: «ثلاثة حق على الله عونهم، منهم: المتزوج يريد العفاف» أو كما قال عليه الصلاة والسلام.\nفالمقصود أن النساء والرجال في حاجة إلى التشجيع على الزواج، وفي حاجة إلى الإعانة وفي حاجة إلى تخفيف المهور، وفي حاجة إلى تخفيف الولائم وتقليلها، كل هذا من أسباب تسهيل الزواج للجميع.\nفنسأل الله أن يوفق الأولياء والنساء جميعاً لما فيه صلاح الجميع، ولما فيه سعادة الجميع، وأن يعيذ الأولياء من الطمع ويعيذ النساء من الطمع أيضاً والتأسي بمن لا يبالي بهذه الأمور، فإن القدوة بأهل الشر لا خير فيها، وإنما القدوة بأهل الخير والاستقامة والعفة وإيثار الآخرة، رزق الله الجميع التوفيق.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/6074/الحث-على-تيسير-المهور-وعدم-استيلاء-الاباء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09814.mp3","categories":["الصداق"]},{"id":8573,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من الأحساء وباعثتها إحدى الأخوات من هناك تقول: (ع. ع. ع) هل يجوز أن أطلب المهر كتاب الله القرآن الكريم، والهدف أن ألاقي ذلك في الآخرة، بما أن قراءتي فيه الحرف بعشر حسنات، أي: أريد أن أكتنزه في الآخرة وليس في الدنيا، وأيضاً أن يكون اليسر والبساطة في مهري؟","title":"حكم جعل المرأة مهرها كتاب الله","answer":"الجواب: المشروع أن يكون المهر مالاً كما قال الله جل وعلا: أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24]، والنبي ﷺ لما جاءته المرأة التي وهبت نفسها فلم يقبلها وأراد أن يزوجها بعض أصحابه قال: التمس ولو خاتم من حديد فالمشروع أن يكون هناك مال ولو قليلاً.\nفإذا كان الزوج عاجزاً ولم يجد مالاً جاز على الصحيح أن يزوج بشيء من الآيات يعلمها المرأة، أو شيء من السور يعلمها المرأة وتكون تلك الآيات أو تلك السور مهراً لها ولا حرج في ذلك، ولهذا زوج النبي ﷺ المرأة الواهبة زوجها بعض أصحابه على أن يعلمها من القرآن كذا وكذا، هذا كله لا بأس به.\nلكن إذا تيسر المال فالمال مقدم ولو قليلاً، والتعليم بعد ذلك إذا أرادت أن يعلمها زوجها يعلمها ما تيسر هذا من باب المعاشرة الطيبة، أن يعلمها ويرشدها ويتعاون معها على الخير هذا شيء آخر، الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، ويقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228]، فإذا عاشرها معاشرة تتضمن تعليمها القرآن وتعليمها السنة وتعليمها أحكام الله فهذا خير كثير، لكن لا يكتفى بهذا في المهر إلا عند الحاجة والعجز عن المال، نعم.\nالملقي: جزاكم الله خيراً","link":"https://binbaz.org.sa/fatwas/6658/حكم-جعل-المراة-مهرها-كتاب-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_208/20806.mp3","categories":["الصداق"]},{"id":8891,"question":"الرسالة التالية وصلت إلى البرنامج من الجمهورية العربية اليمنية باعثها أخونا محمد عبدالله سعيد اليماني يسأل عن القضية المكررة سماحة الشيخ وهي: أكل الوالد من مهر ابنته والتغالي في المهور من أجل الكسب المادي؟","title":"حكم المغالاة في المهور وأخذ الأب من مهر ابنته","answer":"الجواب: هذا السؤال يشمل أمرين:\nأحدهما: المغالاة.\nوالثاني: الأكل من المهر في حق الوالد.\nوالأمران مختلفان في الحكم، أما المغالاة فتكره ولا تنبغي، فينبغي للمسلمين أن لا يغالوا بل ينبغي التسهيل كما جاءت في ذلك الأحاديث والآثار، من الأحاديث قوله ﷺ: خير الصداق أيسره ، فينبغي للمؤمن أن لا يغالي، وينبغي لأهل المرأة أن لا يغالوا، وقد ثبت عنه ﷺ أنه قال لمن خطب: التمس ولو خاتم من حديد ، وزوجه لما لم يجد زوجه على أن يعلمها بعض القرآن، فينبغي في هذا أن لا يغالي أحد في المهور، والنبي ﷺ تزوج على خمسمائة وزوج بناته على أربعمائة، فلو كان التغالي في المهور شرفاً وفضلاً لكان أولى به النبي ﷺ وأصحابه.\nفالمقصود أن التغالي في المهور فيه مفاسد وعواقب لا تحمد، فقد يعطل الشباب ويعطل النساء بأسباب التغالي، وقد يترتب عليه إحن في النفوس وحقد في النفوس على الزوجة وأهلها بسبب المغالاة، وقد لا يقتصر على الزوج بل قد يكون هذا في الزوج وفي أبيه وفي أهله لما رأوا من تكلفه وتعبه.\nفالحاصل أن السنة والذي ينبغي للمؤمنين جميعاً رجالاً ونساءً أن لا يغالوا، وأن يحرصوا على التسهيل والتيسير حتى يتزوج النساء وحتى لا يتعطل الشباب، أما ما يتعلق بأكل الوالد من المهر فالصواب أنه لا حرج في ذلك؛ لأن الأولاد تبع أبيهم، قال النبي ﷺ لرجل قال: يا رسول الله! إن أبي اجتاح مالي؟ قال: أنت ومالك لأبيك، وهو حديث لا بأس به، وقال أيضاً عليه الصلاة والسلام في حديث عائشة: إن أطيب ما أكلتم من كسبكم وإن أولادكم من كسبكم ، وكلاهما حديثان جيدان لا بأس بهما.\nفالحاصل أن انتفاع الوالد من مهر ابنته ليس فيه حرج، ولكن يجب عليه أن يراعي حالها وأن لا يضرها بل يبقي لها ما ينفعها عند زوجها وما تسد به حاجتها لقول النبي ﷺ: لا ضرر ولا ضرار، فكون أولاده من كسبه لا يقتضي أن يضر بالولد أو البنت بل عليه أن يراعي أحوالهما، فإذا كان أخذه من ولده يضره ويضر أولاده وعائلته لم يجز للوالد ذلك وإنما يأخذ ما لا يضر، وهكذا البنت إذا كان أخذه من مهرها يضرها أو يزهد الزوج فيها، أو يسبب طلاقها فلا يتعرض لذلك، وليتق الله ولكن يأخذ من مالها ومن مهرها ما لا يترتب عليه مضرة عليها، والله المستعان. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7047/حكم-المغالاة-في-المهور-واخذ-الاب-من-مهر-ابنته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_140/14004.mp3","categories":["الصداق"]},{"id":9941,"question":"هذه رسالة من السائل أحمد علي حسن الزهراني له فيها عدة أسئلة وإن كان قد تكرر أكثرها سؤال حول تارك الصلاة وهل يدفن في مقابر المسلمين، وسؤال حول غلاء المهور وما نتج عنه من تعطل كثير من الشباب والفتيات عن الزواج بسبب غلاء المهور، ويطلب وضع حل لهذه المشكلة، وسؤال آخر عن دعاء الشياطين والبناء على القبور، هذه خلاصة الأسئلة التي وردت في رسالته؟","title":"حكم ترك الصلاة وغلاء المهور ودعاء أهل القبور","answer":"الجواب: أما السؤال الأول وهو تارك الصلاة هل يدفن في مقابر المسلمين؟ فقد تنازع العلماء في حكمه إذا تركها تهاونًا وهو لم يحل وجوبها بل يؤمن بأن الصلاة فريضة، ولكن تركها تهاونا وكسلًا، فذهب قوم إلى أنه لا يكفر بذلك كفرًا أكبر بل كفر أصغر وأنه يدفن مع المسلمين ويغسل ويصلى عليه، وهذا قول معروف عند جمع كبير من أهل العلم.\nوالقول الثاني أنه يكفر كفرًا أكبر وهذا هو الأصح والأرجح.\nفعلى هذا لا يدفن مع المسلمين بل يدفن في محل بعيد عن الناس لا يعرف ويسوى عليه الأرض كسائر الكفرة؛ لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر ولم يستثن أحدًا، ولم يقل: إذا كان جاحدًا لوجوبها، وهذا حديث صحيح رواه أحمد وأهل السنن بإسناد صحيح، وروى مسلم في صحيحه عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة والكفر معرف والشرك معرف يرجع للكفر الأكبر والشرك الأكبر، هذا هو الأصح والأرجح لأدلة أخرى كثيرة تدل على أن المتهاون في ترك الصلاة ليس معه من الإسلام شيء بل قد فارق الإسلام نسأل الله العافية والسلامة.\nوأما المهور وما يتعلق بغلائها فهذا قد سبق فيه فتاوى كثيرة ونشرنا عن ذلك نشرات كثيرة، وكتب مجلس هيئة كبار العلماء في ذلك كتابات في الحث على عدم المغالاة والاقتصاد في المهور والولائم وهذا حق، فالواجب على المسلمين أن يتعاونوا في هذا وأن يقتصدوا في المهور والولائم حتى يمكنوا المتوسط في الدخل ومن يعجز عن كثير من المهور ومن مئونة الولائم حتى يمكنوهم من الزواج ويسهلوا لهم الزواج.\nفالمقصود أن هذا شيء يجب على المسلمين التعاون فيه وعلى ولاة الأمور التعاون مع الناس في ذلك حتى يتركوا هذه المغالاة في المهور وفي الولائم، وهذا حق على الجميع واوجب على الجميع أن يتعاونوا فيه وأن يتواصوا به لعل الله جل وعلا يمن بترك الناس لهذا الشيء حتى يحسنوا بذلك إلى فقرائهم وإخوانهم الذين يعجزون عن هذه الأمور.\nوأما ما يتعلق بدعوة الشياطين والاستغاثة بالجن وبأصحاب القبور فهذا من الشرك بالله ، فدعاء الأموات والاستغاثة بالأموات والنذر لهم وطلبهم المدد هذا من الكفر الأكبر، وهذا واقع في كثير من الناس في بلدان كثيرة ودول كثيرة يأتي إلى الميت المشهور الذي يسمونه ولي، فيقول: يا سيدي! اشف مريضي رد غائبي المدد المدد، وهذا كفر أكبر بإجماع أهل السنة والجماعة ولا عبرة بمن خالف من المتأخرين الذي جهلوا هذا الأمر ولم يعرفوه وظنوا أن الشرك توحيد وأن التوحيد شرك فهؤلاء لا عبرة بهم.\nفالأدلة من الكتاب والسنة كلها تدل على أن دعاء الأموات والاستغاثة بالأموات وطلبهم المدد من جنس دعاء الأصنام ومن جنس دعاء الكواكب ومن جنس دعاء الأشجار والأحجار كله شرك بالله، كله من عمل الجاهلية، من جنس عمل أبي جهل وأشباهه من كفار قريش حين دعوا العزى وهي شجرة، وحين دعا أهل الطائفة اللات في عهد النبي ﷺ وهي صخرة كان يلت عليها رجل صالح السويق فعظموها وصاروا يعبدونها من دون الله، هذا كله باب واحد فدعاء الأموات والاستغاثة بالأشجار وبالأحجار وبالأصنام وبالكواكب وبالجن كله باب واحد وكله من الشرك بالله .\nفالواجب على أهل الإسلام أن يحذروا هذه الأمور وأن يحذروها الناس، والواجب على العلماء أن يبذلوا وسعهم في هذا الأمر وأن يجتهدوا في تبيين هذا الأمر للناس في الوسائل وسائل الإعلام المنظورة والمقروءة والمسموعة حتى يكون الناس على بينة، فإن كثيرًا من الناس قد وقع في هذا في بلدان كثيرة ودول متعددة يطوف بالقبر ويدعو صاحبه ويستغيث به وينذر له ويذبح له ويطلبه المدد والغوث ويعرض عن الله عز وجل، وهذا من البلاء العظيم. وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14]  فسمى دعاءهم لغير الله شركًا، وهذا يعم دعاء الأموات من الصالحين والأنبياء ويعم دعاء الجن ودعاء الأصنام وغير ذلك، كله شرك بالله  وكله باطل. بخلاف ما فعله .... المشركون الذين جهلوا الأمر وجهلوا الحق فغيروا وبدلوا، نسأل الله السلامة والعافية، نسأل الله أن يهدي المسلمين وأن يبصرهم بدينهم، وأن يوفق علماءهم وحكامهم لتنبيههم وتعليمهم وإرشادهم ومنعهم من الباطل والشرك إنه خير مسئول سبحانه وتعالى.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8109/حكم-ترك-الصلاة-وغلاء-المهور-ودعاء-اهل-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20002.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":9947,"question":"هذا السائل من اليمن يقول: يوجد لدينا في بلدنا نظام من المحكمة أن لا يتجاوز المهر ألفي ريال، وقد عمم ذلك ولكن أولياء الأمور والخاطبون منهم يتفقون فيما بينهم على دفع مبالغ قد تزيد على ستين ألف ريال، ويشترط ولي الفتاة على الزوج أن لا يخبر المحكمة بذلك، وإذا سألت المحكمة قالوا: إن المهر ألفا ريال فقط، ولو علمت المحكمة أو علمت الدولة لدخل واحد منهما السجن، وإذا استمرا في الزواج ووفقا فلا مشكلة، ولكن المشكلة إذا اختلفا وجاءت البنت إلى أهلها وجاء زوجها يريدها قال له أهلها: طلقها، فإذا أراد أن يطلقها وطلب ما عندهم من مال، قالوا: أنت لم تدفع لنا سوى ألفي ريال ولا يستطيع أن يشتكي حتى لا يسجن؛ لأنه متستر، فماذا يفعل في هذه الحالة؟ هل يحق له إذا أكل هؤلاء الناس ماله أن يحرق مزرعة لهم أو يحرق شيئاً لهم انتقاماً أو يضايقهم؟ وهل يجوز لنا أن نقاطع هذا الولي الذي أكل مال هذا الزوج ونترك السلام عليه ونهجره لعل الله أن يهديه، أم ماذا؟","title":"حكم تحديد المهور من المحكمة ومخالفة الناس له","answer":"الجواب: الواجب في هذا عند التنازع الرجوع إلى المحكمة ولو جرى ما جرى من سجن أو غيره، الواجب الرجوع إلى المحكمة حتى تنظر في الأمر، وتجمع بين الزوج والزوجة بالطرق التي تراها المحكمة ولعل الله أن يجعلها سبباً للهداية، وهذا كله بعد العناية، بعد توسيط الرجال الطيبين بينك وبين أهل الزوجة لعل الله أن يهديها فترجع، فترجع إليك والحمد لله، المقصود أن الزواج بما زاد على المحدد فيما بينك وبين أهل المرأة إذا دعت إليه الحاجة والضرورة فلا بأس، حتى لا تجلس بدون زوجة، ولكن ينبغي للجميع أن يتأدبوا وأن يأخذوا بما عينت الدولة وأن يتعاونوا على الخير؛ لأن المغالاة في المهور لا خير فيها قد تضر الجميع قد تعطل الشباب والفتيات، والدولة أرادت الخير وأرادت الإصلاح، فينبغي للشعب رجالاً ونساء أن يتعاونوا مع الدولة، وأن يرضوا بهذا المقرر ولو قليلاً، ومتى صلحت الحال فسوف يعطيها الشيء الكثير، لكن ينبغي للشعب أن يتعاون مع الدولة في قبول ما قرر والرضا به والتسامح حتى لا يتعطل الرجال ولا يتعطل النساء، فإذا قدر أنهما تنازعا بعد ذلك فإنهما يوسطان من أهل الخير من الجيران والأقارب من يصلح بينهما ويفعل الخير بالمفارقة بالمعروف أو بالاجتماع والصلح وعدم وصول المحكمة، فإن دعت الضرورة إلى المحكمة، فإنه لا مانع من الوصول إلى المحكمة وإن جرى ما جرى وإن حبس أو حبس الآخر، أما كونه يحرق أرضه أو مزرعته أو يتعدى، لا، هذا لا يجوز، ولكن يطلب حقه من طريق ولاة الأمور، نسأل الله للجميع الهداية. نعم.\nالمقدم: وإن يعني كان خائف من السجن وسكت؟\nالشيخ: إذا سمح فلا بأس وسوف يجد أمره يوم القيامة سوف يأخذ حقه يوم القيامة.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8118/حكم-تحديد-المهور-من-المحكمة-ومخالفة-الناس-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26710.mp3","categories":["الصداق"]},{"id":10027,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية وباعثها أحد الإخوة المستمعين من هناك رمز إلى اسمه بالحروف (أ. ع. أ. ع) أخونا له جمع من الأسئلة في أحدها يقول:تزوجت فتاة ولم أدفع لها أي مهر على شكل نقود أو ذهب، وذلك برضا الطرفين على الرغم من أنني قادر حيث قمت بتأثيث منزل الزوجية، فهل أنقصتها حقاً من حقوقها، وإن كنت كذلك فهل أستطيع الآن أن أرد لها بعض الشيء أم إلى أهلها جزاكم الله خيراً؟","title":"حكم من تزوج امرأة دون أن يعطيها مهراً","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالواجب أن تعطى شيئاً من المال الزوجة ولو قليلاً إذا رضيت بذلك، سواء كان نقداً أو متاعاً كالملابس أو حلياً من الذهب والفضة وهذا كافي، فإن كنت لم تعطها شيئاً بالكلية فإنك تعطيها مهر المثل، لها المهر الذي يعطاه أمثالها إلا أن تسمح عنك فإذا سمحت فلا حرج عليك والحمد لله.\nوالله جل وعلا قال: أن تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] الزوج يسلم بعض المال ويتفق مع الزوجة على بعض المال أو مع وليها أو يعطيهم ما يتيسر وإذا رضوا بذلك كفى، فإذا كنت أعطيتها شيئاً من المال الذي هو غير النقود من حلي أو ملابس أو أثثت المنزل لها هذا المال لها عطاء لها هذا الأثاث يكون لها ملكاً لها فيكون مهراً لها ولا حرج في ذلك والحمد لله، أما إذا كنت ما أعطيتها شيئاً بالكلية، فإن سمحت عنك وأسقطت عنك المهر فلا حرج، وإذا طلبت شيئاً فأعطها ما يرضيها والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8196/حكم-من-تزوج-امراة-دون-ان-يعطيها-مهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30101.mp3","categories":["الصداق"]},{"id":10074,"question":"مجموعة من الإخوة المستمعين سألوا هذا  لدى أهل قريتنا عادة وهي: إذا زوج الرجل موليته لرجل من خارج القرية، أخذ أهل القرية من ولي المخطوبة مبلغاً معيناً يسمونه مكسر فما حكم ما يفعلون جزاكم الله خيراً؟","title":"حكم دفع بعض المهر لأهل القرية إن كان الزوج من غيرهم","answer":"الجواب: ليس لهم أن يلزموه بذلك، ليس لهم أن يلزموا ولي المرأة بمكسر ولا غيره، بل مهرها لها وليس لوليها إلا الأب فله أن يأخذ منه ما لا يضرها، الأب له أن يأخذ من مهر ابنته ما لا يضرها. أما بقية الأولياء فليس لهم حق في المهر بل الحق بل المهر كله للمرأة، وليس له أن يعطي القبيلة منه شيئاً سواء سمي مكسراً أو غير ذلك، لكن إذا سمحت المرأة في ذلك لمصلحة شرعية لأهل بلدها أن يأخذوا من مهرها ما اعتادوه لمصلحة الفقراء أو لمصالح أخرى لمصلحة القرية ورضيت بذلك وهي رشيدة فلا حرج في ذلك. أما أن يؤخذ من مهرها بغير رضاها أو يؤخذ من مهرها شيء وهي غير رشيدة صغيرة ليست برشيدة أو ليست بثابتة العقل فلا، لابد أن تكون رشيدة عندها عقل وعندها رشد، تحسن التصرف في مالها فإذا سمحت بشيء من مهرها لمصلحة القبيلة التي رآها قومها فلا بأس، أو مصلحة الفقراء أو غير هذا من الأمور الشرعية المباحة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8241/حكم-دفع-بعض-المهر-لاهل-القرية-ان-كان-الزوج-من-غيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30404.mp3","categories":["الصداق"]},{"id":10121,"question":"ما حكم المعونة، وهي الإتيان بشيء خروف أو مال لصاحب العرس؟","title":"حكم مساعدة صاحب العرس","answer":"الجواب: هذا مستحب مساعدته، إذا كان في حاجة مساعدته وإذا كان عرف البلد كذلك، إذا كان في عرف البلد أنه يساعد، أو كان فقير يساعد، كل هذا أمر مطلوب، إن كان عرفًا سوعد، وإن كان فقيراً سوعد، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8292/حكم-مساعدة-صاحب-العرس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27709.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":11106,"question":"المستمع: (م ع. د) من الرياض، يسأل عن الطريقة الصحيحة لدفع المهور، هل مهر البنت يؤخذ لتأثيث بيت الزوجية، أو كيف يكون الحال له؟","title":"حق التصرف في مهر المرأة","answer":"الجواب:  المهر لها، تتصرف فيه على حسب ما تشاء، ليس لتأثيث البيت، المهر لها تحفظه، وتجعله في سكن، في منزل، أو في سيارة، أو في أي شيء، أو تريد تتصدق به إذا كانت رشيدة، هذا مالها. أما تأثيث البيت فهو على الزوج هو الذي يؤثث البيت، وإذا سمحت وشاركته في التأثيث بمهرها أو ببعضه فلا بأس، قال الله سبحانه: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4]، إذا طابت نفسها بشيء وهي رشيدة فلا بأس، سواءً كان المهر كله، أو بعضه. أما الأصل فالأصل أنه ملكها، تتصرف فيه كيف شاءت بما يبيحه الشرع، وليس له الاعتراض عليها في مالها إذا كانت رشيدة، والتأثيث في البيت على الزوج، نعم. المقدم: جزاكم الله خيرًا بالنسبة لحليها وملابسها هل تكون من مهرها، أو تكون من الزوج؟ الشيخ: على حسب ما اصطلحا عليه، إن أعطاها مع الدراهم حليًا فذاك، وإلا لا يلزمه إلا ما اتفقا عليه، الشيء الذي اتفقوا عليه يكفي، فإذا اتفق مع وليها، أو معها على حلي معينة يوفي لها بما شرط، كما قال النبي ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج وفي الحديث الآخر: المسلمون على شروطهم. فإذا اتفق معها، أو مع وليها على دراهم معلومة، أو على حلي معلومة فهم على اتفاقهم، ويلزمه ما اتفقوا عليه، يلزمه تحليل فرجها إلا بذلك، فعليه أن يؤدي ما اتفقا عليه، أما إذا دفع إليهم دراهم معينة ورضوا بها فليس عليه سواها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، أعراف الناس في هذا الموضوع ما هو توجيه سماحة الشيخ تجاهها؟ الشيخ: العرف متبع، إذا كان بين أهل قبيلة أو أهل بلد عرف فعلى الزوج.... إليه، إذا كان عرفًا شائعًا معروفًا، فعلى الزوج في الوليمة، أو في عمل الدخول فعل ذلك الشيء .... به، إذا كان جائزًا شرعًا ليس بمحرم، إذا كان عرفًا جائزًا، ليس فيه محذور، فلا بأس أن يتابعهم عليه، ويرضى به، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9293/حق-التصرف-في-مهر-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36811.mp3","categories":["الصداق"]},{"id":11122,"question":"المستمع: (م ع. د) من الرياض، يسأل عن الطريقة الصحيحة لدفع المهور، هل مهر البنت يؤخذ لتأثيث بيت الزوجية، أو كيف يكون الحال له؟","title":"حق التصرف في مهر المرأة","answer":"الجواب:  المهر لها، تتصرف فيه على حسب ما تشاء، ليس لتأثيث البيت، المهر لها تحفظه، وتجعله في سكن، في منزل، أو في سيارة، أو في أي شيء، أو تريد تتصدق به إذا كانت رشيدة، هذا مالها. أما تأثيث البيت فهو على الزوج هو الذي يؤثث البيت، وإذا سمحت وشاركته في التأثيث بمهرها أو ببعضه فلا بأس، قال الله سبحانه: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4]، إذا طابت نفسها بشيء وهي رشيدة فلا بأس، سواءً كان المهر كله، أو بعضه. أما الأصل فالأصل أنه ملكها، تتصرف فيه كيف شاءت بما يبيحه الشرع، وليس له الاعتراض عليها في مالها إذا كانت رشيدة، والتأثيث في البيت على الزوج، نعم. المقدم: جزاكم الله خيرًا بالنسبة لحليها وملابسها هل تكون من مهرها، أو تكون من الزوج؟ الشيخ: على حسب ما اصطلحا عليه، إن أعطاها مع الدراهم حليًا فذاك، وإلا لا يلزمه إلا ما اتفقا عليه، الشيء الذي اتفقوا عليه يكفي، فإذا اتفق مع وليها، أو معها على حلي معينة يوفي لها بما شرط، كما قال النبي ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج وفي الحديث الآخر: المسلمون على شروطهم. فإذا اتفق معها، أو مع وليها على دراهم معلومة، أو على حلي معلومة فهم على اتفاقهم، ويلزمه ما اتفقوا عليه، يلزمه تحليل فرجها إلا بذلك، فعليه أن يؤدي ما اتفقا عليه، أما إذا دفع إليهم دراهم معينة ورضوا بها فليس عليه سواها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، أعراف الناس في هذا الموضوع ما هو توجيه سماحة الشيخ تجاهها؟ الشيخ: العرف متبع، إذا كان بين أهل قبيلة أو أهل بلد عرف فعلى الزوج.... إليه، إذا كان عرفًا شائعًا معروفًا، فعلى الزوج في الوليمة، أو في عمل الدخول فعل ذلك الشيء .... به، إذا كان جائزًا شرعًا ليس بمحرم، إذا كان عرفًا جائزًا، ليس فيه محذور، فلا بأس أن يتابعهم عليه، ويرضى به، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9293/حق-التصرف-في-مهر-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36811.mp3","categories":["الصداق"]},{"id":11154,"question":"سماحة الشيخ. يقول هذا السائل سماحة الشيخ: هل يجوز للأب أن يأخذ مهر البنت، ولا يعطيها منه شيئًا؟ نرجو من سماحة الشيخ التوجيه في ذلك مأجورين.","title":"حكم أخذ الأب مهر ابنته أو بعضه","answer":"الجواب:  هذا فيه تفصيل: إذا أخذه وجهزها بما يلزم لا بأس، أما يأخذها ولا يعطيها شيئًا ما يجوز، هذا يضرها، لكن له أن يأخذ شيئًا ما يضرها، الجهاز كثير يجهزها منه بما يكفيها، ويأخذ الزيادة ما في بأس، أو يأخذه ويجهزها من عنده بما يلزم، مثل: أخذ المال وصرفه في جهة من الجهات، ولكن جهزها من عنده بما يلزم لا بأس. المقصود ليس له أن يأخذ ما يضرها، يأخذ شيئًا لا يضرها، نعم؛ لقول النبي ﷺ: لا ضرر ولا ضرار أما الأخذ فدليله قول النبي ﷺ: إن أطيب ما أكلتم من كسبكم وإن أولادكم من كسبكم وفي لفظ آخر:  أنت ومالك لأبيك فله أن يأخذ من مال ولده لكن لا يضره؛ لقوله ﷺ: لا ضرر ولا ضرار نعم.","link":"https://binbaz.org.sa/fatwas/9327/حكم-اخذ-الاب-مهر-ابنته-او-بعضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29016.mp3","categories":["الصداق"]},{"id":11513,"question":"حجم المهر يختلف من منطقة إلى منطقة، ومن بلد إلى آخر؟","title":"المعتبر في المهر","answer":"الجواب: ليس له حد محدود، ولو بالقليل، ولو ريالًا أو ريالين، الحمد لله، المقصود وجود مال: أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24]، ولو قليلًا، والحمد لله، فإذا لم يجد مالًا، وتزوجها أنه يعلمها من القرآن، أو يعلمها أحاديث كفى. المقدم: ما شاء الله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9693/المعتبر-في-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38409.mp3","categories":["الصداق"]},{"id":11972,"question":"المستمع محمد سالم رفيع بعث برسالة وضمنها بعض الأسئلة في أحدها يقول: بماذا تنصحون الآباء الذين يكثرون في مهور بناتهم، كأن يطلبوا مبالغ معينة محدودة، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم المغالاة في المهور والإسراف في الولائم","answer":"الجواب:  نصيحتي للجميع التخفيف والتيسير، وعدم طلب الكثير إذا جاء الكفء الطيب، فالمشروع قبوله، وعدم التكلف في المهور، ولا في الولائم، هذا هو الأفضل والأولى والأحوط، لما في ذلك من تكثير الزواج، وإعفاف الرجال والنساء جميعًا، وكثرة الأمة، فالمشروع لأولياء النساء، وللنساء أيضًا أن يتعاونوا في التخفيف، وعدم المطالبة بالمهور الكبيرة، أو بالولائم الكبيرة التي قد تشق على الزوج، وأهل المرأة، وخير الصداق أيسره، فالمشروع التيسير والتسهيل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، هل تقترحون مبلغًا معينًا سماحة الشيخ؟ الجواب: ما جاء في الشرع حد محدود، لكن يختلف هذا بحسب العرف، حسب تغير الأحوال والبلدان والمؤونات، فيستحب التخفيف حسب الطاقة حسب التيسير. المقدم: جزاكم الله خيرًا، إذًا لا تقترحون مبلغًا معينًا؟ الشيخ: لا ما أقترح شيئًا معينًا، إنما التسهيل والتيسير على حسب الأحوال. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10157/حكم-المغالاة-في-المهور-والاسراف-في-الولاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42913.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":12131,"question":"من المستمع عوض من المملكة الأردنية الهاشمية يسأل ويقول: ما رأي سماحتكم فيمن يغالون في المهور، وهل هذا من الإسلام، وما نصيحتكم لمن يفعل ذلك؟ جزاكم الله خيرًا.","title":"نصيحة للمغالين في المهور","answer":"الجواب:  نصيحتي لإخواني في كل مكان عدم المغالاة في المهور، والتخفيف، والتيسير كما في الحديث عن النبي ﷺ أنه قال: خير الصداق أيسره وزوج امرأة إنسانًا على أن يعلمها من القرآن، وقال: التمس ولو خاتمًا من حديد، فالسنة .... المهور، وعدم التكلف؛ حتى يكثر الزواج، وحتى تقل العنوسة، والرجال محتاجون للزواج، والنساء محتاجات للزواج. فالمشروع للأولياء، وللنساء التسامح في المهور، فالمرأة تسامح، وأمها تسامح، وأبوها كذلك، الوصية للجميع التسامح، وعدم التكلف في المهور، ولا في توابع المهور من الولائم وغيرها مهما أمكن، فالوصية التسامح في ذلك، والتخفيف في ذلك حسب الطاقة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10316/نصيحة-للمغالين-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43816.mp3","categories":["الصداق"]},{"id":12505,"question":"من محافظة الحديدة المستمع أحمد سعيد يحيى زغبي بعث يسأل ويقول: ما هو توجيه سماحتكم للآباء الذين يبالغون في المهور، حيث لم يستطع الشباب التقدم للحياة الزوجة، جزاكم الله خيرًا؟","title":"نصيحة وتوجيه للآباء بتخفيف المهور","answer":"الجواب:  نوصي الآباء، وجميع الأولياء بالتخفيف في المهور، وعدم التشديد، وعدم الإكثار والمبالغة، كما نوصي الأمهات والبنات بأن يساعدن في ذلك، نوصي الجميع بالتعاون على هذا الخير، تخفيف المهور حتى يكثر الزواج، وحتى يستعف الشباب رجالًا ونساءً.  فالوصية الوصية التخفيف والتيسير، وعدم التكلف في المهور، وفي الولائم، نوصي الجميع بالتساهل في هذا الأمر، والتخفيف والتيسير، وأن يرضوا بالمهر اليسير، والكلفة اليسيرة، حتى تتزوج النساء، وحتى يستعف النساء، ويستعف الشباب بتوفيق الله، نوصي الجميع بهذا. المقدم: يا الله. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10717/نصيحة-وتوجيه-للاباء-بتخفيف-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40711.mp3","categories":["الصداق"]},{"id":12650,"question":"رسالة مطولة بعض الشيء وصلت إلى هذا البرنامج بتوقيع تسعة وعشرين من المستمعين، هؤلاء الإخوة ذكروا أسماءهم، وقضيتهم التي يشكون منها هي تكاليف الزواج، وكثرة ذلك، هل أقرأ أسماءهم سماحة الشيخ؟","title":"توجيه لأولياء الأمور بتخفيف تكاليف الزواج","answer":"الجواب:  الشيخ: نصيحتي للجميع العناية بتخفيف المهر، والتكاليف الأخرى حتى يتيسر للفتيات وللشباب الزواج، فأوصي جميع المسلمين في هذه البلاد، وفي غيرها، أوصيهم بتسهيل أمر الزواج، لا من جهة المهر، ولا من جهة التكاليف الأخرى، كالوليمة، وغيرها.  فعلى أهل البنت أن يتساهلوا، وأن يقبلوا ما تيسر من الشباب، المهم وجود الشباب الصالح، والزوج الصالح كما في الحديث عنه ﷺ أنه قال: إذا خطب إليكم من ترضون دينه وخلقه؛ فزوجوه، إلا تفعلوه؛ تكن فتنة في الأرض، وفساد كبير فوصيتي للبنات، وأولياء البنات أن يتسامحوا في ذلك، وأن يرضوا بالقليل من المهر على حسب طاقة الخاطب الطيب. وهكذا في الوليمة، والتكاليف الأخرى أوصي الجميع بأن يخففوا منها، ولا يشددوا فيها، وبذلك يحصل للفتيات وللشباب من الرجال الزواج والعفة، وهذا فيه خير عظيم للجميع، يقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع؛ فعليه بالصوم؛ فإنه له وجاء. وأوصي أولياء الأمور بأن يسهلوا في هذا الأمر حسب الطاقة، ومتى حصل التعاون من الأولياء، ومن البنات المزوجات، ومن ولاة الأمور، ومن العلماء، متى حصل التعاون في ذلك؛ حصل خير كثير، إن شاء الله. المقدم: إن شاء الله. الشيخ: نعم. المقدم: جزاكم الله خيرًا، واستجاب لدعوتكم، إنه على كل شيء قدير. الشيخ: اللهم آمين، نعم.","link":"https://binbaz.org.sa/fatwas/10860/توجيه-لاولياء-الامور-بتخفيف-تكاليف-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45802.mp3","categories":["الصداق"]},{"id":13508,"question":"في ثاني أسئلته يقول هذا السائل: لدينا قبيلة -هداهم الله- لا زالوا على بعض العادات، وقد وضعوا طريقة للمهر، وشروط، فمن الناس من رفض ذلك، فهجرناهم، وقررنا أن نهجرهم، وأن نقاطعهم، ولا نحضر احتفالاتهم، أو المناسبات التي يقيمونها، وكان فيهم أقرباء لنا، وجيران، فما رأي سماحتكم؟","title":"حكم مقاطعة وهجر من يغالون في المهور","answer":"الجواب: لا، لا يجوز هجرهم، ولا مقاطعتهم، ولكن ينصحون إذا قرروا المهور لبناتهم لبنته بكذا، وأخته بكذا، ينصحون بالتخفيف. أما هجرهم، هذه لهم شبهة، ما تسمى معصية، لا يهجرون، بل ينصحون، ويوجهون للخير، ويتعاون معهم على الخير والبر بالكلام الطيب، والأسلوب الحسن، مع الرجل، ومع المرأة، ومع أمها، ومع أبيها وعمها، ونحو ذلك من باب التناصح، والتواصي بالحق، هكذا ينبغي. أما الهجران والمقاطعة فلا وجه لهذا؛ لأن لهم شبهة، وقد يكون لهم أسباب، قد يكونوا شرطوا أشياء يحتاجونها، ولا يمكن -يعني- يجرون الزواج إلا بها، لكن إذا كان هناك مهور زائدة، وتكلف زائد ينصحون من باب النصيحة .. من باب التعاون على البر والتقوى .. من باب التواصي بالحق، لا من باب الهجر والشدة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11821/حكم-مقاطعة-وهجر-من-يغالون-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53107.mp3","categories":["الصداق","الآداب والأخلاق"]},{"id":13638,"question":"من أسئلة هذا السائل يقول: ما حكم المال المؤخر، والغير مقبوض من المهر؟","title":"حكم المال المؤخر وغير المقبوض من المهر","answer":"الجواب: هذا حكمه حكم الديون، إن كان على موسر على زوج موسر متى طلبته أعطاها إياه عليها زكاته، فإن كان على معسر، أو ليس لها حق فيه إلا بعد حضور الأجل يعني: بينها وبينه أجل إلى الطلاق، أو إلى الموت؛ فإنها غير قادرة، فليس عليها زكاته كالدين الذي على معسر. أما الدين المؤجل في التجارة والبيع والشراء فهذا يزكى إذا كان على موسر، أما الدين الذي بين المرأة والرجل إذا كان لها دين عليه، وهو معسر؛ فليس عليها زكاة، أو مماطلًا ما أعطاها الدين؛ ليس عليها زكاة، أما إذا كان موسرًا، وليس بمماطل؛ فعليها زكاة الدين الذي لها على زوجها.  والخلاصة: أن الدين إذا كان على معسر، أو إنسان مماطل؛ فلا زكاة على صاحبه، أما إن كان الذي عليه الدين موسرًا، ومتى طلب؛ أدى -سلم- فإن على صاحب الدين أن يزكي هذا الدين كأنه عنده. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11970/حكم-المال-الموخر-وغير-المقبوض-من-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52813.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13686,"question":"بعد ذلك ننتقل إلى رسالة السائل محمد محمدي جميل مقيم بالمدينة النبوية يقول في هذا  هل يجوز أخذ الزيادة في الخلع على ما آتاها من الصداق، وما الدليل على ما تجيبونه؟ جزاكم الله خيرًا.","title":"حكم أخذ زيادة عن الصداق عند الخلع","answer":"الجواب: الأفضل أن لا يأخذ زيادة، هذا هو الأفضل؛ لأن الرسول ﷺ قال لامرأة ثابت بن قيس: تدفعين له الحديقة؟ -الذي أصدقها إياها- قالت: نعم، قال: اقبل الحديقة، وطلقها تطليقة وجاء في بعض الروايات: ولا تزدد لكن في إسنادها نظر، وقال قوم من أهل العلم: إنه يجوز الزيادة؛ لعموم قوله: فَلا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ [البقرة:229] فنفى الجناح فيما افتدت به، يعم مهرها، ويعم ما كان أزيد، لكن الأفضل له، والأحوط ألا يأخذ إلا ما دفع إليها، أو أقل، هذا هو الأحوط، والأفضل؛ خروجًا من الخلاف، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12037/حكم-اخذ-زيادة-عن-الصداق-عند-الخلع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51915.mp3","categories":["الصداق"]},{"id":13739,"question":"تقول السائلة من دمشق: هل في صداق المرأة زكاة؟ وإن كانت لم تقبضه، ولكن زوجها قادر على إيفائه، فوجهونا في ضوء هذا السؤال؟","title":"هل في الصداق الذي لم يقبض زكاة؟","answer":"الجواب: نعم، فيه الزكاة إذا كانت تستطيع أن تقبضه، وهو عند مليء؛ فعليها الزكاة، أما إن كان عند معسر، أو ماطلها، ومنعها؛ فليس عليها زكاة، أما إذا كان موسرًا، وتستطيع أن تقبضه منه؛ فهذا عليها الزكاة، تزكي كل سنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12125/هل-في-الصداق-الذي-لم-يقبض-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53518.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13744,"question":"تقول السائلة من دمشق: هل في صداق المرأة زكاة؟ وإن كانت لم تقبضه، ولكن زوجها قادر على إيفائه، فوجهونا في ضوء هذا السؤال؟","title":"هل في الصداق الذي لم يقبض زكاة؟","answer":"الجواب: نعم، فيه الزكاة إذا كانت تستطيع أن تقبضه، وهو عند مليء؛ فعليها الزكاة، أما إن كان عند معسر، أو ماطلها، ومنعها؛ فليس عليها زكاة، أما إذا كان موسرًا، وتستطيع أن تقبضه منه؛ فهذا عليها الزكاة، تزكي كل سنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12125/هل-في-الصداق-الذي-لم-يقبض-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53518.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13787,"question":"هذا السائل جمال صالح يقول في هذا  سماحة الشيخ! ما حكم الإسلام في نظركم في المغالاة في المهور؟ وعدم تزويج الشباب وتحميلهم أعباء كثيرة على الزواج من حيث الترتيبات؟ وما نصيحتكم لأولياء الأمور في هذه المسألة الخطيرة التي يجب أن تعالج من قبلكم؟ جزاكم الله خيرًا.","title":"توجيه في تيسير المهور وعدم المغلاة فيها","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فنصيحتي لجميع المسلمين من الرجال والنساء عدم المغالاة في المهور وعدم التكلف تسهيلًا للزواج لعفة الرجال والنساء جميعًا، فهذه نصيحتي لهم، وقد جاءت الأحاديث والآثار عن السلف بالدلالة على ذلك فالسنة للمؤمن عدم المغالاة.\nوعلى أولياء الأمور أن يتقوا الله في هذا الأمر وأن يحرصوا على تزويج بنيهم وبناتهم بالطرق الممكنة الميسرة التي ليس فيها ضرر على الجميع، والأوقات تختلف، ولكن يتحرون المهر المناسب الذي يحصل به المطلوب من دون مشقة على الزوج؛ لأن كثيرًا من الناس قد يتأخر عن الزواج بسبب المغالاة لا يقدر، وربما تعطل كثير من النساء بسبب ذلك وحصل من الفساد ما لا يحصيه إلا الله .\nفالمشروع للجميع العناية بهذا الأمر؛ الرجل يعتني والمرأة تعتني، الرجل يعتني ويحرص على التخفيف والتيسير لتزويج بناته وأخواته وغيرهم، والنصيحة لهن في ذلك، والمرأة كذلك تتقي الله وتحرص على التخفيف مع بنتها ومع أختها ومع قريباتها حتى يتعاون الجميع على التخفيف والتيسير، وبهذا يتيسر الزواج لجميع الشباب من الرجال والنساء، ولا يخفى أن وجود الزواج مع المئونة القليلة خير من تعطيل الرجل أو تعطيل المرأة، كونها تتزوج ويعفها الرجل بمهر مناسب ليس فيه تكلف خير لها في الدنيا والآخرة، وهكذا الرجل كونه يتزوج ويتيسر له المرأة المناسبة من دون تكلف خير له في الدنيا والآخرة، فالجميع عليهم التعاون والتواصي بهذا الأمر لعل الله جل وعلا يكتب لذلك النجاح. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12146/توجيه-في-تيسير-المهور-وعدم-المغلاة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53001.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":13827,"question":"في آخر أسئلة السائل من اليمن يقول في هذا  أرجو من سماحة الشيخ أن يحدثنا عن حلي النساء، وهل فيه زكاة أم لا؛ لأننا نسمع البعض يقول: بأن عليه زكاة، وهل إذا كان معد للزينة فهل تزكي عليه المرأة؟ وإذا كانت تزكي عليه فما هو المقدار الذي يزكى عليه؟ وإذا لم يكن لديها مال فهل يزكي عنها الزوج، أو الأب، أو الأخ؟ وهل يجوز أن تبيع منه وتزكي عنه؟","title":"حكم زكاة الحلي والبيع منه لأجل الزكاة","answer":"الجواب: الزكاة في الحلي مسألة خلاف بين العلماء، والأرجح والأصح فيما يظهر لي من دلالة الأدلة الشرعية وجوب الزكاة في الحلي من الذهب والفضة، وهو الذي أفتي به من دهر طويل ولم أفت بغيره، وهو وجوب الزكاة في الحلي إذا بلغ الذهب نصابًا أو الفضة، والنصاب عشرون مثقالًا من الذهب، ومائة وأربعون مثقالًا من الفضة، ومقدار ذلك أحد عشر جنيهًا وثلاثة أسباع جنيه من الجنيه السعودي، ومن الفضة ستة وخمسون ريالًا من الفضة أو ما يقوم مقامها من العُمَل الورقية، وإذا كانت الزوجة لا تستطيع الزكاة؛ لعدم وجود مال عندها تبيع منه وتزكي، وإن زكى عنها زوجها بإذنها كفى والحمد لله، إذا زكى عنها زوجها أو أبوها أو ولدها بإذنها كفى وإلا فعليها أن تزكي إما باقتراض من غيرها، أو ببيع شيء منه وتزكي. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12194/حكم-زكاة-الحلي-والبيع-منه-لاجل-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53708.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13965,"question":"الأخت المستمعة أم أحمد من المنطقة الشمالية رفحا بعثت برسالة وعرضنا جزءًا من أسئلتها في حلقة مضت: أملك بعض الحلي من الذهب أكثر من النصاب، ولكني لا أستعمله كله، حيث أحتفظ ببعضه كي ينفع أولادي البنين عند زواجهم، حيث أنهم ما زالوا في مرحلة التعليم، والنقود سرعان ما نتصرف فيها بعكس الذهب، وسؤالي: هل أدفع زكاة الذهب الذي لا أستعمله فقط حتى وإن كان أقل من النصاب، أم يجب علي دفع زكاة جميع ما عندي من ذهب؟","title":"حكم الزكاة في الذهب المدخر والمستعمل","answer":"الجواب: الصواب: أن عليك زكاة الجميع، وقد ذهب بعض أهل العلم إلى أن الحلي المستعملة لا زكاة فيها، ولكنه قوله مرجوح، والصواب الذي عليه الأدلة الشرعية: أن الحلي تزكى، سواء كانت مدخرة أو مستعملة أو معارة، الواجب أداء الزكاة فيها إذا بلغت النصاب، والنصاب عشرون مثقالًا من الذهب، ومقداره بالجنيه السعودي: إحدى عشر جنيهًا وثلاثة أسباع جنيه، يعني: إحدى عشر جنيهًا ونص، فإذا بلغت الحلي هذا المقدار؛ وجبت الزكاة فيها، ربع العشر كل سنة، فإذا كانت ..... تبلغ عشرة آلاف مثلاً، إذا كانت الحلي تبلغ عشرة آلاف؛ ففيها مائتان وخمسون، ربع العشر، ربع الألف العاشر مائتان وخمسون، وهكذا، وهي بالغرام قريب من اثنين وتسعين غرامًا، يعني: إحدى وتسعون غرامًا وكسور، فإذا زكت ما بلغ هذا المقدار، اثنين وتسعين غرامًا تقريبًا، وهو إحدى عشر جنيهًا ونص سعودي، فإذا زكت هذا المقدار فهو الواجب عليها، وهكذا ما زاد عليه.\nأما إذا كان أقل من ذلك، فليس فيه شيء؛ لأن النصاب شرط في وجوب الزكاة، وقد ثبت عنه ﷺ أنه قال: ما من صاحب ذهب ولا فضة لا يؤدي حقها؛ إلا إذا كان يوم القيامة صفحت له صفائح من نار، فيكوى بها جنبه وجبينه وظهره، في يوم كان مقداره خمسين ألف سنة، ثم يرى سبيله إما إلى الجنة، وإما إلى النار.. الحديث، متفق على صحته.\nوجاءته ﷺ امرأة ومعها ابنتها وفي يدها سواران من ذهب قال: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؛ فألقتهما وقالت: هما لله ولرسوله. وسألته أم سلمة رضي الله عنها، وكانت تلبس أوضاحًا من ذهب فقالت: يا رسول الله! أكنز هذا؟ فقال عليه الصلاة والسلام: ما بلغ أن يزكى فزكي؛ فليس بكنز، فدل ذلك على أن ما لا يزكى يعتبر كنز، يستحق صاحبه العقوبة، فالحلي التي لا تزكى من الكنوز، كالجنيهات المحفوظة، وقطع الذهب المحفوظة إذا بلغ النصاب يسمى كنزًا، وإن كان على وجه الأرض، وإن كان في المخازن الظاهرية في الصناديق، كل شيء لا تؤدى زكاته -وهو من أموال الزكاة- يعتبر كنزًا؛ يعذب به صاحبه يوم القيامة. نسأل الله العافية.\nفعليكِ أيها الأخت في الله! أن تؤدي الزكاة عن الملبوس والمحفوظ جميعًا، إذا بلغ الجميع النصاب، وفقك الله ويسر أمرك. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12380/حكم-الزكاة-في-الذهب-المدخر-والمستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60504.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13981,"question":"يسأل أخونا ويقول: هل تجب الزكاة على الذهب الخاص بالزوجة والبنات، والمشترى بقصد استعماله للزينة، أم لا تجب في ذلك زكاة؟","title":"هل تجب الزكاة في الذهب المشترى للزينة؟","answer":"الجواب: هذه مسألة اختلف فيها العلماء رحمة الله عليهم، منهم من أوجب فيها الزكاة؛ لعموم الأدلة، ولأدلة خاصة، ومنهم من قال: إنها لا تجب؛ لأنها مستعملة.\nوالصواب أنها تجب الزكاة في الحلي إذا بلغ النصاب ولو أنه مستعمل؛ لعموم قوله ﷺ: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار؛ فيكوى بها جنبه وجبينه وظهره.. الحديث.\nولما ثبت عنه ﷺ: أنه جاءته امرأة وفي يد ابنتها مسكتان من ذهب -يعني: سوارين من ذهب- فقال: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار، فألقتهما، وقالت: هما لله ولرسوله.\nفالمقصود أن الحلي داخلة في عموم الأدلة الدالة على وجوب الزكاة في الذهب والفضة، ومن هذا ما في حديث أم سلمة أنها قالت: يا رسول الله! -كانت تلبس أوضاحًا من ذهب، فقالت: يا رسول الله! أكنز هذا؟ فقال عليه الصلاة والسلام: ما بلغ أن يزكى فزكي فليس بكنز، ولم يقل لها: ليس في الحلي زكاة.\nأما حديث: «ليس في الحلي زكاة»، فهو حديث لا يصح عن النبي عليه الصلاة والسلام.\nوالخلاصة: أن الصحيح من قولي العلماء: أن في الحلي زكاة -في الذهب والفضة- إذا بلغت النصاب، والنصاب عشرون مثقالًا، ومقدار ذلك بالجنيه السعودي: أحد عشر جنيهًا وثلاثة أسباع جنيه، يعني: أحد عشر جنيهًا ونص؛ لأن الفرق يسير، ومن الفضة: مائة وأربعون مثقالًا، ومقدار ذلك بالفضة بالريال السعودي: ستة وخمسون ريالًا من الفضة، وما يعادلها من العمل.  فإذا بلغت الحلي هذا المقدار؛ وجب على صاحبتها الزكاة إذا حال عليها الحول، والواجب ربع العشر، فإذا كانت الحلي تبلغ عشرة آلاف؛ ففيها مائتان وخمسون، ربع العشر، وإذا كانت تبلغ عشرين ألفًا؛ ففيها خمسمائة ربع العشر، وهكذا، وذلك يزيدها خيرًا ويبرئ ذمتها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12396/هل-تجب-الزكاة-في-الذهب-المشترى-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60602.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14002,"question":"هل تزكى حلي المرأة كل عام؟ أم يكفي تزكيتها مرةً واحدة في العمر؟","title":"حكم زكاة الحلي في كل عام","answer":"الجواب: كل عام، الواجب كل عام، مثل بقية الذهب، كل عام تزكى، مثل بقية الذهب والفضة إذا كان غير حلي، هذا هو الصواب. نعم، إذا كان يبلغ النصاب.\nالمقدم: لسؤاله تكملة يقول فيها: مع العلم أنها لو زكيت كل عام، لكان معنى ذلك أن المرأة تدفع ثمنًا آخر لحليها، وقيمة الحلي ثابتة لا تنمو؟\nالشيخ: نعم عليها أن تدفع الزكاة ولو ما نمت، مثل الذي عنده ذهب في الصندوق، يزكيه ولو أنه في الصندوق، كل سنة يزكيه ولو ما نما، عليه الزكاة من يمنعه من التنمية، فالحلي الذي يبلغ النصاب عليها أن تزكيه، مواساة للفقراء والمحاويج، وإذا نقص عن النصاب ما فيه زكاة، أما مادام يبلغ النصاب عشرين مثقالًا اثنين وتسعين غرامًا فإنها تزكيه ربع العشر، في كل ألف خمسة وعشرون، في المائة اثنين ونص، هذا ظاهر الأحاديث الصحيحة عن رسول الله ﷺ، بعض أهل العلم يرى أنه لا زكاة في الحلي لأنها مستعملة، ولكن الصواب: أن فيها الزكاة لعموم الأدلة، لقوله ﷺ: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها، إذا كان يوم القيامة صفحت له صفائح من نار. الحديث، ولم يستثن الحلي، ولقوله ﷺ لما رأى امرأةً عليها أسورة: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار، فألقتهما، قالت: هما لله ولرسوله. ولم يقل لها: ما عليها زكاة، بل أمرها بالزكاة، وهي حلي في أيديها، هكذا أم سلمة رضي الله عنها، كان عليها أوضاحًا من ذهب، فقالت: يا رسول الله! أكنز هذا؟ قال: ما بلغ أن يزكى فزكي فليس بكنز . قال: (فزكي) ولم يقل: أن الحلي ليست من الكنز، ولم يقل لها: .. لا زكاة فيها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12416/حكم-زكاة-الحلي-في-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48306.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14100,"question":"تقول أختنا: عندي ست حبات بناجر وقلادة ذهب، هل يجب عليها زكاة؟","title":"وجوب الزكاة فيما بلغ النصاب من الحلي","answer":"الجواب: نعم، الصواب فيها الزكاة إذا بلغت النصاب، ولو كانت تلبس أو تعار، الصواب فيها الزكاة إذا كانت تبلغ أحد عشر جنيهًا ونص، عشرين مثقالا، وذلك ما يقارب اثنين وتسعين غرامًا، فإذا كانت تبلغ هذا؛ ففيها الزكاة، وأما إن كانت أقل من هذا المقدار، يعني: أقل من أحد عشر جنيهًا ونص، أقل من تسعين غرامًا؛ فليس فيها زكاة. نعم.\nوالزكاة ربع العشر، الزكاة ربع العشر، في المائة اثنان ونص، في الألف خمسة وعشرون، في العشرة الآلاف مائتان وخمسون، وهكذا ربع العشر، يعني: سهم من أربعين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12534/وجوب-الزكاة-فيما-بلغ-النصاب-من-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61007.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14132,"question":"إذا حدث في مجتمع ما أن تباهى الناس بارتفاع المهور ووصلت مهور النساء إلى مبلغ لا يطيقه كثير من الشباب فهل لهم أن يجمعوا على أن يكون المهر مبلغ كذا ومن تجاوز هذا المبلغ يكون عليه ما هو كيت وكيت من الجزاءات؟","title":"حكم اتفاق القبيلة على مهر معين","answer":"الجواب: لا نعلم حرجًا في ذلك، إذا رأى شيوخ القبائل وقادة البلد الاجتماع على مهر معين لتسهيل الزواج وعفة الرجال والنساء فلا حرج في ذلك، وقد وقع هذا لقبائل كثيرة وجاءت إلى هيئة كبار العلماء ووافقوا على ذلك، فلا حرج في ذلك أن يجتمع قادة البلد وقادة القبيلة مثلاً فيجتمعوا على أن المهر يكون خمسين ألفًا.. أربعين ألفًا.. عشرين ألفًا.. عشرة آلاف، يلاحظون الشيء الذي يناسب المقام؛ لأن الأحوال تغيرت ما هي مثل الحالات القديمة، فلا بد يراعون أحوال الناس وحاجات الناس فيحددوا شيئًا مناسبًا يبذله الزوج للمرأة ليس فيه إجحاف بالمرأة وليس فيه مضرة على الزوج حتى يتضرر وحتى لا يتيسر له الزواج، ولكن يتوسطون ويتشاورون حتى يهديهم الله لمبلغ مناسب يسهل على الزوج وينفع الزوجة، وإذا اتفقوا عليه وجب تنفيذه ومنع من يخالفه؛ لأنه لمصلحة الجميع، والله ولي التوفيق . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12572/حكم-اتفاق-القبيلة-على-مهر-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61508.mp3","categories":["الصداق"]},{"id":14189,"question":"هذه السائلة (ن. ح) رمزت لاسمها بهذا الرمز تقول: أهدتني إحدى الأخوات أسورة ولم ألبسها إلا مرتين، وكذلك أعطتني المدرسة سبيكة ذهبية صغيرة فهل علي في هذا الذهب إخراج للزكاة، وكيف أقوم بإخراجه علمًا بأنني لم أشتريه بل أهدي إلي وهو عندي من حوالي أربع سنوات؟","title":"حكم الزكاة في الذهب المُهدى","answer":"الجواب: نعم، عليك الزكاة، إذا بلغت النصاب هذا الهدية أو عندك ما يكمل النصاب فعليك الزكاة كل سنة، من حين ملكتها لكن إذا كنت جاهلة سقطت الزكاة عنك في هذا الحلي حتى يتم الحول بعدما علمت ووجهت إلى الخير، وإن زكيت عما مضى فهو أحوط، أما الوجوب فلا يجب عليك إلا بعدما علمت؛ لأن زكاة الحلي فيها خلاف بين أهل العلم، وأنت لم تعلمي فليس عليك شيء حتى بلغك العلم.\nفالمقصود أنك تزكين هذه إذا حال عليها الحول وكانت تبلغ النصاب أو عندك ما يكمل النصاب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12642/حكم-الزكاة-في-الذهب-المهدى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54721.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14276,"question":"المستمع سودان فراج الحارثي بعث يسأل ويقول: يوجد عند زوجتي ذهب تقدر قيمته بأكثر من خمسين ألف ريال، هل تجب فيه الزكاة علمًا بأنها تلبسه دائمًا وهي تقصد منه الاستعمال للزينة فقط؟","title":"حكم زكاة الحلي ومقدار نصابها","answer":"الجواب: الواجب في الحلي الزكاة في أصح قولي العلماء ولو كانت تستعمل ذلك، الواجب عليها الزكاة هذا هو الصحيح وهي ربع العشر من الأربعين ألف ألف واحد، ومن عشرة آلاف مائتان وخمسون، يعني: ألف ومائتان وخمسون في الخمسين الألف ربع العشر.\nوالله جل وعلا أوجب على عباده الزكاة في الذهب والفضة وفي الإبل والبقر والغنم الراعية وفي عروض التجارة، فلا يجوز للمؤمن أن يتساهل في هذه الأمور، وهكذا أوجبها عليهم في الحبوب والثمار، وقد ثبت عنه ﷺ أنه قال: ما من صاحب ذهب ولا فضة لا يؤدي حقها وفي لفظ آخر: لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار فيكوى بها جنبه وجبينه وظهره في يوم كان مقداره خمسين ألف سنة حتى يقضى بين الناس ثم يرى سبيله إما إلى الجنة وإما إلى النار. وهذا وعيد عظيم يعم ذهب الحلي وفضة الحلي وغيرها، ولأنه ثبت عنه ﷺ أنه دخلت عليه امرأة في يد ابنتها مسكتان من ذهب -يعني: سوارين من ذهب- فقال: أتؤدين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار، فألقتهما وقالت: هما لله ولرسوله. رواه الإمام أبو داود والإمام النسائي رحمة الله عليهما في سننهما بإسناد صحيح.\nوثبت عن أم سلمة رضي الله عنها أنها كانت تلبس أوضاحًا من ذهب فقالت: يا رسول الله! أكنز هذا؟ فقال ﷺ:  ما بلغ أن يزكى فزكي فليس بكنز، ولم يقل لها: ليس في الحلي زكاة بل قال: ما بلغ أن يزكى يعني: ما بلغ النصاب فزكي فليس بكنز، أما ما لم يزك وقد بلغ النصاب فإنه كنز يعذب به صاحبه يوم القيامة، يشير إلى قوله جل وعلا: وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ [التوبة:34].\nفالحاصل: أن الحلي من الذهب والفضة التي تستعملها النساء فيها الزكاة إذا بلغت النصاب والنصاب عشرون مثقالًا ومقداره أحد عشر جنيه ونصف، ومقداره بالغرامات اثنان وتسعون غرامًا فإذا كان الذهب أقل من هذا فلا زكاة فيه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12736/حكم-زكاة-الحلي-ومقدار-نصابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48611.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14351,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع عبدالله حامد عبود، الأخ عبدالله عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة له سؤال طويل جدًا عن غلاء المهور، وهل يعتبر المهر الغالي بمثابة بيع البنت -كما يقول-؟يرجو التوجيه، جزاكم الله خيرًا.","title":"الحث على التيسير في المهور","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالشرع المطهر لم يحدد في المهر شيئًا معلومًا، بل أطلق للناس ما يتفقون عليه من المهور قليلةً أو كثيرة، لكن الشارع رغب في التقليل والتيسير ترغيبًا في النكاح، وعفة الرجال والنساء، ومن ذلك قوله : خير الصداق أيسره وكان زوج بناته على خمسمائة وتزوج على خمسمائة، ويروى أنه زوج بناته على أربعمائة. فالمقصود: أنه ﷺ كان يحث على تخفيف المهور وتيسيرها، ولم يغال فيها لا مع أزواجه ولا مع بناته -عليه الصلاة والسلام-، فالمشروع للمؤمن أن يخفف، وأن لا يتكلف في ذلك، ولكن الأوقات تختلف في الغلاء والرخص، وتيسر الحاجات، وعدم تيسرها، فيشرع لأهل الزواج أن يتفقوا على شيء مناسب ليس فيه إجحاف بالزوج، ولا مضرة على الزوج، ولا تعطيل للنساء والشباب، كل ما كان ذلك أيسر وأقل كان أفضل حتى يتيسر للجميع حصول النكاح؛ لقوله ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم، فإنه له وجاء. فالمؤمن يحرص على أن يقدم بنته وأخته وموليته بكل وسيلة شرعية حتى لا تتعطل، وحتى لا تتعرض للأخطار، والرجل كذلك يحرص على أن يتزوج، ويحرص أبوه وأخوه والقادر على تزويجه، والتعاون معه في ذلك حتى لا يتعرض لأخطار العزوبة، ولا سيما في هذا العصر الذي كثرت فيه الفتن، وكثر فيه المتبرجات من النساء.","link":"https://binbaz.org.sa/fatwas/12823/الحث-على-التيسير-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_620/62001.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":14548,"question":"السائل سعيد محمد مصري، يقول في هذا يوجد عندنا في القرية إذا تزوج الشاب بفتاة أو شرع في الزواج منها فيخير بين أمرين، وهما:أولاً: أن يدفع لوالد العروس مهرًا، وفي هذه الحالة يقوم والد العروس بتجهيز المنزل المعد للزواج.ثانيًا: أن يقوم الشاب بتجهيز المنزل، وفي هذه الحالة لا يدفع لوالد العروس شيئًا من المال. علمًا بأن الزوج هو الذي يقوم ببناء البيت، فأيهما أفضل يا سماحة الشيخ من جهة الشرع هل هو دفع المهر، أم تجهيز المنزل؟","title":"ما الأفضل للعريس دفع المهر؟ أم تجهيز المنزل؟","answer":"الجواب: الأمر في هذا واسع، والحمد لله، الله يقول: أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] فإذا تراضى الزوج والمرأة وأبوها على شيء في تجهيز المنزل، أو تسليم نقود، أو نقود وتجهيز، أو غير ذلك فلا بأس الأمر إليهم.  المهم أن يبذل مالًا ترضى به المرأة، ولا بأس، سواء قليل أو كثير، النبي ﷺ قال لرجل: التمس ولو خاتمًا من حديد والله يقول: أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] والمال يعم القليل والكثير، فإذا تراضوا على شيء من تجهيز منزل، أو تسليم نقود، أو نقود وتجهيز أو غير هذا من وجوه المصالحة بينهما، فالأمر واسع في هذا، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13045/ما-الافضل-للعريس-دفع-المهر-ام-تجهيز-المنزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55509.mp3","categories":["الصداق"]},{"id":14571,"question":"في ثاني أسئلة هذا السائل من الجزائر يقول في سؤاله: هل يخول الشرع الزوجة الناشز في كل ما تطلبه من أغنام ولباس وأواني أكل وطبخ وغطاء وأثاث؟وجهونا في ضوء هذا السؤال.","title":"هل يجب إعطاء الناشز شيئًا من المهر؟","answer":"الجواب: الناشز لا حق لها في مهرها، إذا كانت ناشزة بغير حق ظالمة؛ ولهذا لما نشزت امرأة ثابت بن قيس على زوجها ثابت قال النبي ﷺ: أتردين عليه حديقته؟ قالت: نعم، فقال لزوجها: اقبل الحديقة، وطلقها تطليقة لأنها نشزت عليه بغضًا له وسخطًا، لم يتعد عليها، ولم يظلمها، إنما هي مبغضة، فأمرها النبي ﷺ أن ترد عليه مهره. فالناشز بغير حق عليها أن ترد المهر كله، فيطلقها الزوج؛ لأن هذا خير له من وجودها معه، وهي تبغضه، فإذا ردت عليه ماله يؤمر بطلاقها، ولا حق لها في مهرها، سواء كان مهرها نقودًا أو بيتًا أو أرضًا أو أمتعة عليها أن ترد عليه مهره إلا إذا سمح بالبعض، ورضي بالنصف أو بالربع فلا بأس.  أما إذا أبى إلا مهره كله فإنها تعطيه مهره كله إذا لم يظلمها إنما هي مبغضة له، أما إذا ظلمها فهذا ينظر فيه القاضي يتحاكما إلى المحكمة والمحكمة تنظر في الأمر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13068/هل-يجب-اعطاء-الناشز-شيىا-من-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55609.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14801,"question":"يقول: إذا دفع الرجل جزءًا بسيطًا من المهر، وسيدفع الباقي فيما بعد، هل تكون المرأة زوجة له؟ وهل له الحق في الدخول عليها، أما لا بد من دفع المهر كاملًا قبل الدخول على المرأة؟وهل هناك شيء يدفعه الزوج لوالد الفتاة، أقصد شيئًا غير مهر الزوجة يكون لا بد من دفعه لوالد الفتاة، أم أن ذلك أمر اختياري؟ وجهونا، جزاكم الله خيرًا.","title":"حكم تعجيل المهر وتأخيره ودفع شيء لوالد الزوجة","answer":"الجواب: المهر لا بأس أن يعجل، ولا بأس أن يؤخر، ولا بأس أن يعجل بعضه، ويؤخر بعضه، فليس من شرط النكاح تقديم المهر، فإذا تزوجها على مبلغ معلوم يسلمه لها بعد شهر أو شهرين أو سنة أو سنتين، أو عند الطلاق، فلا بأس بذلك، وإن تزوجها على أنه يقدم لها ألفًا أو ألفين أو أكثر أو أقل، والباقي يكون عند الطلاق أو في وقت آخر معلوم فلا بأس بذلك، كله لا حرج فيه، والحمد لله. أما والدها وإخوتها فليس لهم شيء، المهر كله للمرأة، لكن لو تبرع لوالدها أو لإخوتها بشيء فلا بأس، أما المهر المشروط في النكاح فهو للمرأة، ولوالدها أن يشرط شيئًا لنفسه خاصة، للوالد خاصة، وهو الأب، لا بأس أن يشرط شيئًا لنفسه، لا حرج في ذلك إذا التزم به الزوج يعطيه إياه.  وأما بقية الأولياء فليس لهم حق في ذلك، إلا أن تعطيهم البنت المرأة شيئًا من ذلك، وهي مرشدة باختيارها فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13319/حكم-تعجيل-المهر-وتاخيره-ودفع-شيء-لوالد-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63815.mp3","categories":["الصداق"]},{"id":14868,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، ضمنها خمسة أسئلة، المستمع هو جمال عبده أحمد صالح الشعبي من اليمن، يقول في رسالته:أرجو من سماحة الشيخ التوجيه والنصح للآباء الذين يحتكرون بناتهم طمعًا في كثرة المهر؛ ولهذا السبب اختلط الحابل بالنابل، وأصبح الناس يتلهفون وراء المادة، ولا يبالون بمن يزوجون، والذي لديه ثروة مالية يقبل ما فرضه عليه الأب من مهر، وتكاليف باهضة، وأصبح الفقير عاجزًا عن الزواج، ولا يلتفت إليه أحد، بل ينظرون إليه بعين الاحتقار، فما هو رأي سماحتكم؟ وما هو توجيهكم؟بارك الله فيكم.","title":"نصيحة بعدم المغالاة في المهور","answer":"الجواب: الواجب على الأولياء سواءً كانوا آباءً أو إخوة أو أعمامًا أو غيرهم، الواجب عليهم تقوى الله ، وأن يخافوا الله في مولياتهم، وأن يجتهدوا في تزويجهن على الأكفاء، ولو بالمهور القليلة، وأن لا يتكلفوا في ذلك لا في المهر، ولا في الوليمة.  الواجب التماس الأكفاء الأخيار الطيبين، ولو كانوا فقراء، لكن يستطيعون المهر، ويستطيعون النفقة على زوجاتهم. وفي الحديث عنه -عليه الصلاة والسلام- أنه قال إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد عريض. فالمؤمن يتحرى الزوج الصالح لبنته وأخته وابنة أخيه ونحو ذلك، ولا يهمه المال، يهمه الرجل الصالح ولو كان المهر قليلًا، ولو كانت التكاليف قليلة، ولو كانت الوليمة قليلة، هذا هو الواجب على الأولياء، ولا يجوز لهم أن يحبسوا النساء لطلب كثرة المال، هذا غلط كبير وشر عظيم، وقد يزوجون من ليس بكفء لأجل المال، ويدعون الكفء لأجل قلة المال، وهذا منكر، وخيانة للأمانة، فالموليات أمانة عند الأولياء. فالواجب على الأولياء أن يتقوا الله في الأمانة، وأن يلتمسوا للأمانة الرجل الصالح الطيب، وإذا لم يوجد إلا ناقصون يختار الأفضل، فالأفضل والأقل شرًا، حتى لا تعطل البنات والأخوات، هذا هو الواجب على الجميع، مع تقوى الله في ذلك، والحذر من ظلم النساء، والحرص على تزويجهن بمن يخطب من الأكفاء، ولو قل المال، ولو قلت التكاليف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13366/نصيحة-بعدم-المغالاة-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64509.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":14870,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، ضمنها خمسة أسئلة، المستمع هو جمال عبده أحمد صالح الشعبي من اليمن، يقول في رسالته:أرجو من سماحة الشيخ التوجيه والنصح للآباء الذين يحتكرون بناتهم طمعًا في كثرة المهر؛ ولهذا السبب اختلط الحابل بالنابل، وأصبح الناس يتلهفون وراء المادة، ولا يبالون بمن يزوجون، والذي لديه ثروة مالية يقبل ما فرضه عليه الأب من مهر، وتكاليف باهضة، وأصبح الفقير عاجزًا عن الزواج، ولا يلتفت إليه أحد، بل ينظرون إليه بعين الاحتقار، فما هو رأي سماحتكم؟ وما هو توجيهكم؟بارك الله فيكم.","title":"نصيحة بعدم المغالاة في المهور","answer":"الجواب: الواجب على الأولياء سواءً كانوا آباءً أو إخوة أو أعمامًا أو غيرهم، الواجب عليهم تقوى الله ، وأن يخافوا الله في مولياتهم، وأن يجتهدوا في تزويجهن على الأكفاء، ولو بالمهور القليلة، وأن لا يتكلفوا في ذلك لا في المهر، ولا في الوليمة.  الواجب التماس الأكفاء الأخيار الطيبين، ولو كانوا فقراء، لكن يستطيعون المهر، ويستطيعون النفقة على زوجاتهم. وفي الحديث عنه -عليه الصلاة والسلام- أنه قال إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد عريض. فالمؤمن يتحرى الزوج الصالح لبنته وأخته وابنة أخيه ونحو ذلك، ولا يهمه المال، يهمه الرجل الصالح ولو كان المهر قليلًا، ولو كانت التكاليف قليلة، ولو كانت الوليمة قليلة، هذا هو الواجب على الأولياء، ولا يجوز لهم أن يحبسوا النساء لطلب كثرة المال، هذا غلط كبير وشر عظيم، وقد يزوجون من ليس بكفء لأجل المال، ويدعون الكفء لأجل قلة المال، وهذا منكر، وخيانة للأمانة، فالموليات أمانة عند الأولياء. فالواجب على الأولياء أن يتقوا الله في الأمانة، وأن يلتمسوا للأمانة الرجل الصالح الطيب، وإذا لم يوجد إلا ناقصون يختار الأفضل، فالأفضل والأقل شرًا، حتى لا تعطل البنات والأخوات، هذا هو الواجب على الجميع، مع تقوى الله في ذلك، والحذر من ظلم النساء، والحرص على تزويجهن بمن يخطب من الأكفاء، ولو قل المال، ولو قلت التكاليف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13366/نصيحة-بعدم-المغالاة-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64509.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":14928,"question":"أحد الإخوة بعث برسالة يبدو أنه نسي أن يذكر اسمه، وسؤاله طويل في الواقع، ملخصه: رجل طلق قبل الدخول بزوجته وبعد الخلوة، فهل له أن يسترد المهر؟","title":"حكم إرجاع المهر لمن طلق زوجته بعد الخلوة","answer":"الجواب: إذا طلق بعد الخلوة الكاملة، حيث أغلق الباب، وتمكن من جماعها، فإنها لا ترد عليه شيئًا إذا طلق، يكون لها المهر كاملًا؛ لأن الخلفاء الراشدين -رضي الله عنهم- قضوا بأن الخلوة بمنزلة المسيس، فليس له شيء، وعليها العدة. أما إذا كانت الخلوة لا في محل مكشوف، أو في محل ليس هناك رادع من الدخول عليهم، فإنها لا تسمى خلوة، ويكون له النصف إذا طلقها يكون له النصف؛ لقوله تعالى: وَإِنْ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ [البقرة:237] والخلوة التي لا يتمكن معها من الجماع؛ لأن الباب.....، أو مردود ردًا لم يغلق، فهذا لا تمنع التنصيف، بل يبقى له النصف لأنها خلوة غير معتبرة، نعم. المقدم: وإذا كانت الخلوة كاملة لكنه لم يتمكن من الدخول لمرض ونحوه؟\nالشيخ: نعم، ليس له النصف، تنزل منزلة الجماع، يكون لها المهر كاملًا، وعليها العدة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13425/حكم-ارجاع-المهر-لمن-طلق-زوجته-بعد-الخلوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49206.mp3","categories":["الصداق"]},{"id":15081,"question":"مع مطلع هذه الحلقة نعود إلى رسالة المستمع محمد بن علي حمدان تهامي، عندي ثلاثة أولاد، وعند أخي المتوفى ثلاث بنات وولدان، وعندما توفي أخي، زوجت أولادي ببناته بدون مهر ولا شيء، على أساس إذا كبر أولاده؛ أزوجهم ببناتي، وعندما كبرت بنتي زوجتها بشخص آخر، ولم أعطهم شيئًا، فما حكم ذلك؟","title":"حكم الزواج دون تعيين مهر مسمى","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن هذا الزواج صحيح، والحمد لله، وجزاك الله خيرًا؛ لأنك محسن وعملت من باب صلة الرحم، ولا حرج في ذلك، إلا أن لهن المهر، لبنات أخيك المهر على أولادك؛ لأنه لا بد من مهر، لكن إذا سمحن عن ذلك، بعد ذلك فلا حرج؛ لأن الله قال: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] وليس...\nالمقدم: نعيد الآية لو تكرمتم سماحة الشيخ؟\nالشيخ: يقول الله -جل وعلا-: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] فإذا سمحت البنات عن المهر فلا حرج في ذلك بعد رشدهن، وإلا فالواجب لهن المهر. أما أنت فإن زوجت بناتك على أولاده فقد أحسنت وإلا فليس بلازم، ثم أيضًا لا بد من رضاهن، لا بد من رضا البنات، فإذا كان البنات لا يرضين بأولاد أخيك، لا تجبرهن، فإن رضين فزوجهن بأبناء أخيك ولا يكن هذا شغارًا؛ لأن هذا مجرد نية في قلبك فلا يكن شغارًا. أما لو كانوا شرطوا عليك، كانوا كبارًا وشرطوا عليك يكون شغارًا، والشغار لا يجوز، لكن ما داموا صغارًا، ونويت أن تزوجهم بناتك، ثم زوجت بعض بناتك على غيرهم، فلا حرج في ذلك، ولا يكون شغارًا، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13578/حكم-الزواج-دون-تعيين-مهر-مسمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49401.mp3","categories":["الصداق"]},{"id":15097,"question":"المرسل سالم جبار المجهلي، من خميس مشيط، بعث بهذه الرسالة، يقول فيها: هل يجوز للرجل أن يتزوج بمهر ابنته إن كان غنيًا أو فقيرًا؟","title":"حكم تزوج الأب بمهر ابنته","answer":"الجواب: لا حرج عليه؛ لأن الولد من كسبه، وقد قال النبي ﷺ: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم وقال لآخر قال له: «يا رسول الله، إن أبي اجتاح مالي، قال: أنت ومالك لأبيك فلا حرج على الرجل أن يتزوج من مال بنته، أو من مهر بنته، لا حرج عليه في ذلك إذا كانت بنته غير محتاجة لهذا الشيء، أما إذا احتاجت، فإنه يبدأ بها يعطيها حاجتها لزوجها، مما يتجمل به النساء، يعطيها حاجتها من مهرها، والباقي لا بأس أن يأخذه، وإن سمحت له بذلك كله، وهي رشيدة، فلا بأس بذلك، لكن إذا كانت غير رشيدة، أو لم تسمح فإنه يعطيها حاجتها، ولا يأخذ ما يضرها، والفاضل لا بأس أن يأخذه.","link":"https://binbaz.org.sa/fatwas/13599/حكم-تزوج-الاب-بمهر-ابنته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66406.mp3","categories":["الصداق"]},{"id":15282,"question":"سؤالها الآخر تقول فيه: لقد كثر الاختلاف في وجوب زكاة الذهب الذي يلبس وليس للإعارة أو الإيجار، فما هو رأي الدين في ذلك؟","title":"حكم زكاة الذهب الذي يلبس للزينة","answer":"الجواب: العلماء اختلفوا في الذهب والفضة الذي تتحلى به المرأة، وتلبسه عند الحاجة، هل يزكى أم لا يزكى؟ وهل تكفي العارية؟ على أقوال لأهل العلم، والأرجح والأصح أنه يزكى، وأنه تجب فيه الزكاة إذا بلغ النصاب، والنصاب عشرون مثقالًا، ومقداره بالجنيه السعودي إحدى عشر جنيه ونصف بالجنيه السعودي، والفرنجي أيضًا، إحدى عشر جنيهًا وثلاثة أسباع جنيه، يعني: إحدى عشر جنيه ونصف أوضح للسامع، إحدى عشر جنيهًا ونصف هذا النصاب. فإذا بلغ حلي المرأة من الذهب إحدى عشر جنيهًا ونصف وجبت عليها الزكاة، في الألف خمسة وعشرون ريالًا، في الألف الريال خمسة وعشرون ريالًا، في الذهب الذي قيمته ألف خمسة وعشرون ريالًا مثلًا، وهكذا.\nالمقدم: ربع العشر، يعني.\nالشيخ: ربع العشر، كسائر أنواع الذهب والفضة؛ ربع العشر، أما إن كان أقل من عشرين مثقالًا، يعني: أقل من إحدى عشر جنيهًا ونصف فلا شيء فيه، هذا هو الصواب، وهذا هو الأرجح من أقوال أهل العلم؛ لأنه ثبت عنه ﷺ أنه دخلت عليه امرأة وفي يدها سواران مسكتان من ذهب، فقال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتها وقالت: هما لله ولرسوله.  وقالت له أم سلمة: يا رسول الله -وكانت تلبس أوضاحًا من ذهب- هل في هذا زكاة؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز سألته: هل هذا كنز؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز. ولعموم الحديث: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار... الحديث، فإنه يعم هذه الحلي، نعم.","link":"https://binbaz.org.sa/fatwas/13789/حكم-زكاة-الذهب-الذي-يلبس-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67508.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15359,"question":"سماحة الشيخ، هذه سائلة تقول: ما مقدار زكاة الذهب؟ وهل ذهب الزينة له زكاة؟بينوا لنا ذلك، مأجورين.","title":"نصاب زكاة الذهب وحكم زكاة الحلي","answer":"الجواب: زكاة الذهب ربع العشر، وهكذا الفضة ربع العشر، من كل مائة اثنان ونصف ومن الألف خمسة وعشرون.\nوهي واجبة في الحلي التي تلبسها المرأة على الصحيح، فإذا كانت تبلغ النصاب وجبت فيها الزكاة، سواء كانت قلائد أو أسورة، أو حزامًا، أو غير ذلك، الواجب فيها الزكاة، والنصاب عشرون مثقالاً من الذهب، يعني: مقداره أحد عشر جنيهًا ونصف من الجنيهات السعودية، اثنان وتسعون غرامًا من الغرامات، فإذا كان عند المرأة نصاب من الحلي وجبت فيها الزكاة إذا حال عليها الحول، فإذا كانت الحلي تبلغ مثلًا عشرين ألفًا، عليها الزكاة ربع العشر خمسمائة؛ لأن عشر العشرين ألفان، ربع العشر خمسمائة، فإذا كانت تبلغ خمسين ألفًا الحلي، صار فيها ربع العشر عشرها خمسة آلاف، ربع العشر ألف ومائتان وخمسون، سواء ذهب أو فضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13862/نصاب-زكاة-الذهب-وحكم-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49902.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15514,"question":"تقول هذه السائلة يا سماحة الشيخ: اشتريت ذهبًا يبلغ النصاب في شهر صفر، ثم اشتريت ذهبًا آخر أيضًا يبلغ النصاب في شهر رمضان، كيف أخرج الزكاة؟ وهل في الذهب المستعمل زكاة؟","title":"حكم زكاة الحلي وكيفية إخراجها","answer":"الجواب: الصواب الحلي فيها الزكاة، هذا هو الراجح، فالذي اشتريتيه في صفر زكيه إذا جاء صفر، والذي في رمضان إذا جاء رمضان، كل واحد إذا حال عليه الحول، الذهب الذي في صفر يزكى في صفر إذا حال عليه الحول، والذي في رمضان يزكى في رمضان إذا كان نصابًا، والنصاب إحدى عشر جنيهًا ونصف، إحدى عشر جنيهًا وثلاثة أسباع جنيه، عشرون مثقالًا من الذهب، فإذا بلغ النصاب الذي ملكته في صفر زكيه، ويضم إليه الذي ملكته في رمضان يزكى إذا جاء رمضان، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14052/حكم-زكاة-الحلي-وكيفية-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69107.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15532,"question":"سؤاله الثاني يقول: تحتفظ زوجتي بقدر من الذهب بقصد الزينة، فهل تجب عليه الزكاة، خاصة وأننا سمعنا في هذا الموضوع آراء عدة؟أفتونا، جزاكم الله خيرًا.","title":"حكم الزكاة في الحلي المعد للزينة","answer":"الجواب: اختلف العلماء في الحلي المعدة للبس والملبوسة، والصواب في ذلك أن فيها الزكاة، هذا هو الصواب؛ لعدة أحاديث وردت في الباب، فإذا بلغ مجموع الحلي من قلائد وأسورة ونحو ذلك نصاب الزكاة وهو عشرون مثقالًا من الذهب؛ وجبت فيها الزكاة، ومقدارها بالعملة الموجودة أحد عشر جنيه سعودي ونصف، هي ثلاثة أسباع جنيه، لكن الثلاثة الأسباع قرب النصف، والنصف أوضح للناس.  فالحصيلة: أنها أحد عشر جنيه ونصف، إذا بلغت الحول بهذا المقدار أو أكثر من ذلك؛ ففيها الزكاة، فإن كانت أقل من هذا فلا زكاة فيها، ولو كانت ملبوسة، هذا هو الصواب من قولي العلماء، نعم.","link":"https://binbaz.org.sa/fatwas/14070/حكم-الزكاة-في-الحلي-المعد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70304.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15564,"question":"من أسئلة هذه السائلة تسأل: هل زكاة الذهب ضروري، وإذا كان لبسه في المناسبات وليس للبيع والشراء؟ أفيدونا بذلك.","title":"حكم إخراج الزكاة عن الذهب المعد للبس","answer":"الجواب: الصحيح وجوب الزكاة في الحلي من الذهب والفضة، هذا هو الراجح من أقوال العلماء؛ إذا بلغ النصاب، وحال عليه الحول، على المرأة أن تزكي ذهبها فضةً أو ذهبًا إذا حال عليه الحول، وكان نصابًا، نعم. المقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14100/حكم-اخراج-الزكاة-عن-الذهب-المعد-للبس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69131.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15577,"question":"لها سؤال آخر تقول: ما هو الحكم بالنسبة لزكاة الحلي: الذهب أو الفضة إذا وجبت الزكاة فيهما، فما هو النصاب؟ وهل يقدر على أساس الوزن، أم العيار؟","title":"حكم زكاة الحلي ونصابها","answer":"الجواب: الذهب والفضة من الأموال الزكوية، ويقدر النصاب بالوزن، فنصاب الذهب عشرون مثقالًا، ومقدار ذلك أحد عشر جنيهًا ونصف الجنيه من الجنيه السعودي، واثنان وتسعون غرامًا بالغرام.  ومقدار نصاب الفضة مائة وأربعون مثقالًا، ومقدار ذلك ستة وخمسون ريالًا بالفضة، فإذا بلغ النصاب ما ذكر وجبت الزكاة، ولو كانت حليًا من الذهب أو الفضة، فإنها تزكى متى بلغت النصاب وجب أن تزكى وإن كانت حليًا تلبس على الصحيح من أقوال العلماء؛ لما ورد في هذا من الأحاديث الصحيحة؛ ومن جملتها: حديث عبد الله بن عمرو بن العاص -رضي الله عنهما-: «أن امرأة أتت النبي ﷺ وعليها مسكتان من ذهب فقال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما، وقالت: هما لله ولرسوله، وهكذا حديث ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار الحديث، وهكذا حديث أم سلمة: «أنها كانت تلبس أوضاحًا من ذهب فقالت: يا رسول الله، أكنز هذا؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز. فدل ذلك على أن ما لم يزك من الحلي وغيرها من الذهب والفضة، فإنه يسمى كنزًا، يعذب صاحبه، نسأل الله السلامة. فالخلاصة: أن الحلي تزكى، ولو كانت تلبس من الذهب والفضة، إذا بلغت النصاب، وهو أحد عشر جنيهًا ونصف من الذهب، ومائة وأربعون مثقالًا من الفضة، وبالمثاقيل في الذهب عشرون مثقالًا من الذهب، وبالغرامات اثنان وتسعون غرامًا من الذهب، فإذا بلغ هذا زكي، فالاعتبار بالوزن. أما من جهة القيمة فينظر قيمته وقت الحول في السوق ماذا يساوي الذهب في السوق؟ فيزكى حسب القيمة، وإن كان كثيرًا وزكاه من الذهب كفى، فلو كانت الحلي تبلغ أربعين جنيهًا زكاها بجنيه واحد ربع العشر، فإن عشر أربعة الجنيهات عشرها الربع، فيها واحد، فإذا أخرج جنيهًا واحدًا وأعطاه بعض الفقراء كفى، وإن أخرج قيمته من النقود ووزعه بين الفقراء كفى، نعم. المقدم: نعم.","link":"https://binbaz.org.sa/fatwas/14118/حكم-زكاة-الحلي-ونصابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69203.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15643,"question":"هذا سؤال من الأخت المستمعة (أ. ص. ع) من جمهورية مصر العربية، تقول: أملك حليًا ذهبية وألبسها، وقد اشتريتها منذ زمن، ولكني كل فترة أزيد عليها إلى أن بلغ ثمنها الآن حوالي ألف وخمسمائة جنيه مصري، فهل يحق دفع زكاة على هذه الحلي؟ أم أنها تعتبر زينة أتحلى بها؟وكذلك لي طفلة صغيرة اشتريت لها ذهبًا؛ لكي تلبسه، وأنا أحتفظ لها بهذا الذهب حتى تكبر فتلبسه، أي: أنه يكون مثل المال المركون، وثمنه حوالي ثمانمائة جنيه مصري، فهل يجب عليه دفع زكاة لهذا الذهب؛ لأن الله  توعد الذين يكنزون الذهب والفضة بعذاب أليم إن لم يخرجوا زكاتهما، وإذا لم يكن عليه زكاة فما معنى الكنز إذًا؟","title":"حكم إخراج الزكاة عن الذهب المعد للزينة","answer":"الجواب: هذه المسألة فيها خلاف بين أهل العلم في حلي المرأة التي تلبسها، والصواب أن فيها الزكاة، هذا هو الأرجح من أقوال أهل العلم، أن فيها الزكاة في حلي المرأة، وحلي البنت جميعًا إذا بلغ كل منهما النصاب، والنصاب عشرون مثقالًا من الذهب مقداره اثنان وتسعون غرامًا وهو بالجنيه السعودي أحد عشر جنيهًا ونصف الجنيه، فإذا كان الذهب الذي لديك يبلغ هذا المقدار ففيه الزكاة، وهكذا الذي عند ابنتك إذا كان بلغ هذا المقدار فيه الزكاة وهي ربع العشر من كل ألف خمسة وعشرون، من كل ألف خمس وعشرون، هذا هو الزكاة في الذهب ولو كان يلبس ولو كان للزينة، هذا هو المختار؛ لقول النبي ﷺ للمرأة التي جاءت إليه وفي يد ابنتها مسكتان من ذهب: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله ولرسوله».\nوكانت أم سلمة -رضي الله عنها- تلبس أوضاحًا من ذهب فقالت: «يا رسول الله، أكنز هذا؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز فدل ذلك على أن الحلي تعتبر كنزًا إذا لم تزك. فالواجب عليك إخراج الزكاة عن حليك وعن حلي البنت إذا بلغ كل منهما النصاب الذي سمعتيه؛ وهو عشرون مثقالًا من الذهب، وبعبارة أخرى: اثنان وتسعون غرامًا، وبعبارة ثالثة: أحد عشر جنيهًا ونصف ذهب سعودي أو فرنجي الموجود الآن، هذا هو مقدار النصاب، فإذا كان أقل من هذا فليس فيه زكاة. والواجب ربع العشر، يعني: سهم من أربعين، من كل ألف خمسة وعشرون، هذا هو الواجب في الذهب والفضة، نعم.","link":"https://binbaz.org.sa/fatwas/14188/حكم-اخراج-الزكاة-عن-الذهب-المعد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_697/nour_69704.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":16256,"question":"تقول: هل المهر من أركان الزواج؟ وما الدليل على ذلك؟ جزاكم الله خيرًا.","title":"حكم المهر","answer":"الجواب: ليس المهر من أركانه، ولا من شرائطه، ولكنه لابد منه؛ لأن الله يقول -لما ذكر النكاح- قال: وَأُحِلَّ لَكُمْ مَا وَرَاءَ ذَلِكُمْ أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] وإذا تزوجها بدون مهر، وجب لها مهر المثل، والنكاح صحيح، لو قال: زوجتك، يقول ولي المرأة للزوج: زوجتك وهي راضية، ويقول الزوج: قبلت، بحضرة شاهدين، وليس هناك موانع صح النكاح، إذا كانت المرأة ليس فيها مانع، ليست محرمة على الزوج، وليست في إحرام، وليست في عدة، ليس بها مانع من النكاح وراضية، وزوجها الولي، وقبلت، وقبل الزوج بحضرة شاهدين؛ النكاح صحيح، ولو لم يسم مهرًا، لكن يجب لها مهر المثل، لأن النبي ﷺ حكم بذلك، في حديث معقل بن سنان الأشجعي: أن رجلًا تزوج امرأة، ولم يسم لها مهرًا، وتوفي عنها، فقال النبي ﷺ: لها مهر نسائها، لا وكس، ولا شطط، وعليها العدة، ولها الميراث. المقصود: أن هذا هو الحكم فيمن تزوج، ولم يسم مهرًا، على أن لها مهر المثل، سواء كان حيًا، أو ميتًا، إن مات فتعطى من تركته، وإن كان حيًا عليه أن يسلم لها المهر إذا دخل بها، إذا وطئها، أو خلا بها، إذا وطئها، أو خلا بها. أما إن عقد عليها، ثم طلق؛ فإن لها المتعة، يمتعها بما يسر الله، من كسوة أو مال، لقول الله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا [الأحزاب:49] وقال سبحانه: لا جُنَاحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتَاعًا بِالْمَعْرُوفِ حَقًّا عَلَى الْمُحْسِنِينَ [البقرة:236] فليس لها مهر المثل في هذه الحال، ولكن يمتعها، على الموسع قدره، وعلى المقتر قدره، المؤسر يمتعها بجارية، أو بمهر أمثالها، أو بأقل من ذلك حسب ما يتيسر، والمعسر ولو بالقليل، ولو بكسوة، جاء عن ابن عباس -رضي الله تعالى عنهما-: \"أن أعلى المتعة جارية، وأدناها كسوة\". والمقصود من هذا: أن المؤسر يمتع بأحسن مما يمتع المعسر، المؤسر يمتع بشيءٍ رفيع، من جاريةٍ يعطيها إياها أي: مملوكة، أو مالٍ كثير يعني: يقارب المهر، أو يقارب نصف المهر، يمتعها بشيء يعتبر فوق ما يمتعها به الفقير، والفقير يمتع بقدر استطاعته من كسوةٍ مناسبة حسب طاقته، أو دراهم، الله -جل وعلا- أطلق، ولم يحدد  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14950/حكم-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80804.mp3","categories":["الصداق"]},{"id":16264,"question":"تقول: هل المهر من أركان الزواج؟ وما الدليل على ذلك؟ جزاكم الله خيرًا.","title":"حكم المهر","answer":"الجواب: ليس المهر من أركانه، ولا من شرائطه، ولكنه لابد منه؛ لأن الله يقول -لما ذكر النكاح- قال: وَأُحِلَّ لَكُمْ مَا وَرَاءَ ذَلِكُمْ أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] وإذا تزوجها بدون مهر، وجب لها مهر المثل، والنكاح صحيح، لو قال: زوجتك، يقول ولي المرأة للزوج: زوجتك وهي راضية، ويقول الزوج: قبلت، بحضرة شاهدين، وليس هناك موانع صح النكاح، إذا كانت المرأة ليس فيها مانع، ليست محرمة على الزوج، وليست في إحرام، وليست في عدة، ليس بها مانع من النكاح وراضية، وزوجها الولي، وقبلت، وقبل الزوج بحضرة شاهدين؛ النكاح صحيح، ولو لم يسم مهرًا، لكن يجب لها مهر المثل، لأن النبي ﷺ حكم بذلك، في حديث معقل بن سنان الأشجعي: أن رجلًا تزوج امرأة، ولم يسم لها مهرًا، وتوفي عنها، فقال النبي ﷺ: لها مهر نسائها، لا وكس، ولا شطط، وعليها العدة، ولها الميراث. المقصود: أن هذا هو الحكم فيمن تزوج، ولم يسم مهرًا، على أن لها مهر المثل، سواء كان حيًا، أو ميتًا، إن مات فتعطى من تركته، وإن كان حيًا عليه أن يسلم لها المهر إذا دخل بها، إذا وطئها، أو خلا بها، إذا وطئها، أو خلا بها. أما إن عقد عليها، ثم طلق؛ فإن لها المتعة، يمتعها بما يسر الله، من كسوة أو مال، لقول الله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا [الأحزاب:49] وقال سبحانه: لا جُنَاحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتَاعًا بِالْمَعْرُوفِ حَقًّا عَلَى الْمُحْسِنِينَ [البقرة:236] فليس لها مهر المثل في هذه الحال، ولكن يمتعها، على الموسع قدره، وعلى المقتر قدره، المؤسر يمتعها بجارية، أو بمهر أمثالها، أو بأقل من ذلك حسب ما يتيسر، والمعسر ولو بالقليل، ولو بكسوة، جاء عن ابن عباس -رضي الله تعالى عنهما-: \"أن أعلى المتعة جارية، وأدناها كسوة\". والمقصود من هذا: أن المؤسر يمتع بأحسن مما يمتع المعسر، المؤسر يمتع بشيءٍ رفيع، من جاريةٍ يعطيها إياها أي: مملوكة، أو مالٍ كثير يعني: يقارب المهر، أو يقارب نصف المهر، يمتعها بشيء يعتبر فوق ما يمتعها به الفقير، والفقير يمتع بقدر استطاعته من كسوةٍ مناسبة حسب طاقته، أو دراهم، الله -جل وعلا- أطلق، ولم يحدد  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14950/حكم-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80804.mp3","categories":["الصداق"]},{"id":16305,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع سالم سعيد عبد الولي يمني مقيم في المملكة، يسأل لو تكرمتم ويقول: يوجد في قريتنا مسجد يصلي فيه الناس، وكذلك يجتمع فيه الناس من القرى المجاورة لأداء صلاة الجمعة، ولكن هناك عادة اعتاد الناس عليها وهي: إذا نوى أحدهم إقامة زواج؛ أخبر الناس بذلك في المسجد بعد صلاة الجمعة، فهل هذا جائز؟","title":"حكم الدعوة إلى وليمة العرس في المسجد","answer":"الجواب: لا نعلم بأسًا في ذلك، هذا ليس من إنشاد الضالة، هذه دعوة إلى الوليمة، قد وقع مثل هذا في عهد النبي ﷺ فأرسل له بعض الصحابة يدعوه، فقال للحاضرين: توجهوا إلى فلان يدعوكم إلى وليمة، ولم ينكر ذلك على من دعاه، أرسل أبو طلحة أنسًا في بعض الأيام يدعو النبي ﷺ إلى وليمة، فقال للحاضرين: قوموا إلى دعوة أبي طلحة. فالمقصود: أن هذا لا بأس به، إذا قال شخص من الحاضرين: تفضلوا للعشاء، أو للغداء؛ لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15000/حكم-الدعوة-الى-وليمة-العرس-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81003.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":16312,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع سالم سعيد عبد الولي يمني مقيم في المملكة، يسأل لو تكرمتم ويقول: يوجد في قريتنا مسجد يصلي فيه الناس، وكذلك يجتمع فيه الناس من القرى المجاورة لأداء صلاة الجمعة، ولكن هناك عادة اعتاد الناس عليها وهي: إذا نوى أحدهم إقامة زواج؛ أخبر الناس بذلك في المسجد بعد صلاة الجمعة، فهل هذا جائز؟","title":"حكم الدعوة إلى وليمة العرس في المسجد","answer":"الجواب: لا نعلم بأسًا في ذلك، هذا ليس من إنشاد الضالة، هذه دعوة إلى الوليمة، قد وقع مثل هذا في عهد النبي ﷺ فأرسل له بعض الصحابة يدعوه، فقال للحاضرين: توجهوا إلى فلان يدعوكم إلى وليمة، ولم ينكر ذلك على من دعاه، أرسل أبو طلحة أنسًا في بعض الأيام يدعو النبي ﷺ إلى وليمة، فقال للحاضرين: قوموا إلى دعوة أبي طلحة. فالمقصود: أن هذا لا بأس به، إذا قال شخص من الحاضرين: تفضلوا للعشاء، أو للغداء؛ لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15000/حكم-الدعوة-الى-وليمة-العرس-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81003.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":16351,"question":"تسأل سماحتكم شيخ عبدالعزيز فتقول: هل أزكي الحلي التي أتحلى بها غالب الأحيان؟","title":"زكاة الحلي المستعمل","answer":"الجواب: الحلي من الذهب والفضة فيها خلاف بين العلماء، جماعة من العلماء يقولون: لا زكاة فيها إذا كانت تستعمل، وآخرون يقولون: فيها الزكاة، ولو أنها تستعمل إذا بلغت النصاب، وهذا القول أصح، الأصح من أقوال العلماء أنها تزكى، إذا بلغت النصاب؛ لأنه جاء في الأحاديث ما يدل على ذلك.. جاءته امرأة في يدها مسكتان -يعني سوارين- من ذهب فقال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟. وقال لعائشة لما كان عندها فتخات لا تزكيها هي حسبك من النار. وقال لأم سلمة، وكانت تلبس أوضاحًا من ذهب قالت: أكنز هما؟ فقال: ما زكي فليس بكنز فدل على أن هذه الحلي تزكى، وإن لم تزك؛ فهي كنز، يعذب به صاحبه. فالواجب على النساء إذا كان عندهن حلي من الذهب والفضة تبلغ النصاب الواجب عليهن الزكاة في أصح قولي العلماء إذا كانت الحلي تبلغ النصاب، والنصاب أحد عشر جنيهًا ونصفًا، يعني عشرين مثقالًا، اثنين وتسعين غرامًا تقريبًا، فإذا كانت الحلي تبلغ هذا؛ وجبت الزكاة في الذهب، أما الفضة فنصابه مائة وأربعون مثقالًا، يعني ستة وخمسون ريالًا، بالريال السعودي الفضة، إذا بلغت الفضة هذا النصاب يعني: ستة وخمسون ريالًا، يعني: مائة وأربعون مثقالًا فإنها تزكى، هذا هو الصواب، هذا هو الأرجح، وهذا هو الحق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15045/زكاة-الحلي-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71414.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":16762,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من ليبيا، صاحبها ضمن رسالته أكثر من قضية، إحدى القضايا يقول: إنه تكلف مبلغًا كبيرًا في الزواج، ورغم مضي فترة طويلة إلا أنه لم يستطع تسديد ما بقي عليه من المهر لأبي زوجته، ويسأل: هل عليه أن يفي بكل ما كان في ذلكم العقد، وهل لعمه أن يطالبه شرعًا بدفع ذلك المبلغ، وصاحب الرسالة من ليبيا؟","title":"حكم تسديد الزوج ما بقي عليه من مهر زوجته","answer":"الجواب: يقول النبي ﷺ في الحديث الصحيح: إن أحق الشروط أن يوفى به ما استحللتم به الفروج فالواجب عليك أن تؤدي ما التزمت به، وشرط عليك من المال، إلا أن يسمح والدها، ويتحمل، أو تسمح هي عن حقها، فإذا سمحت، أو سمح والدها فالحمد لله. أما ما داما يطالبان بالحق؛ فعليك أن توفي إذا استطعت، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] يقول الله سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280] إذا كنت معسرًا؛ يجب عليهما إنظارك، أما إن كنت موسرًا؛ فالواجب أن تؤدي ما التزمت به، واستحللت به فرج المرأة، لقول النبي ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج متفق على صحته، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15515/حكم-تسديد-الزوج-ما-بقي-عليه-من-مهر-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82202.mp3","categories":["الصداق"]},{"id":16768,"question":"سماحة الشيخ لعل المستمع ينتظر كلمة من سماحتكم حول تيسير أمر الزواج؟","title":"توجيه حول تيسير أمور الزواج","answer":"الجواب: الزواج قد تم، إنما عليه الآن الوفاء بما التزم، لكن نوصي غيره بالتسهيل في المهور، وعدم التكلف، ينبغي للمؤمن ألا يتكلف، أو المرأة، وأخوها، وكذلك هي وأمها؛ ينبغي لهم التسامح في الأمور وعدم التشديد، وأن تكون المهور على حسب حال الزوج، لا يكلف ما لا يطيق، بل ينبغي التخفيف، والتيسير في المهور، وفي الولائم أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15517/توجيه-حول-تيسير-امور-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82203.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":17064,"question":"من المستمع: عبدالمعطي عبدالمجيد رسالة ضمنها سؤالًا يقول فيه: قرأت في أحد كتب الأحاديث عن النبي -عليه الصلاة والسلام- حديثين:عن ابن عباس -رضي الله عنهما- قال: لما تزوج علي فاطمة -رضي الله عنها- أراد أن يدخل بها، فمنعه رسول الله ﷺ حتى يعطيها شيئًا، فقال: ليس لي شيء، فقال -عليه الصلاة والسلام-: أعطها درعك فأعطاها درعه، ثم دخل بها، أخرجه أبو داود والنسائي .أما الحديث الآخر وهو عن عائشة -رضي الله عنها- قالت: \"أمرني رسول الله ﷺ أن أدخل امرأةً على زوجها قبل أن يعطيها شيئًا\" أخرجه أبو داود، وقد وجدت ببصيرتي الضيقة اختلافًا، أو تناقضًا بين هذين الحديثين من حيث المعنى، والمغزى، والنتيجة، رغم أن الإخراج قوي، فهل سمحتم لي يا سماحة الشيخ، ونورتموني، وشرحتم لي هذين الحديثين جيدًا؟ جزاكم الله خيرًا.","title":"حكم الدخول بالمرأة قبل إعطائها المهر","answer":"الجواب: الأولى والأفضل أن يقدم للزوجة مهرها، وما تم بينهما، فإن سمحت وأجلت عليه فلا حرج، وقصة فاطمة لعلها -رضي الله عنها- أبت أن يدخل عليها حتى يعطيها شيئًا، فأمر النبي ﷺ بذلك، أمر عليًا أن يعطيها الدرع الحطمية، ثم دخل عليها، فلعل السبب أن فاطمة أرادت ذلك وطلبت ذلك، وهذا حق لها، فلهذا أمره ﷺ أن يسلمها إياه يعني: الدرع، أما المرأة الأخرى فقد رضيت فلا حرج. المقصود: أن المهر حق المرأة، فإذا طلبته وهو معجل ليس بمؤجل فإنه يلزمه أن يسلمه لها، ولا يلزمها أن تسلم نفسها حتى يعطيها مهرها الذي شرطته، أو شرطه وليها برضاها، أما إذا كان المهر مؤجلًا أو سمحت أن تؤجله، وأن تؤخره عليه، فالحق لها ولا حرج.  فحديث فاطمة ..قصة فاطمة محمول على أن فاطمة -رضي الله عنها- لم ترض إلا بتقديم الدرع، أو أن النبي ﷺ رأى أن تقديم الدرع لا بد منه لأسباب اقتضت ذلك، والنصوص لا يخالف بعضها بعضًا، ولا ينقض بعضها بعضًا، بل هي متوافقة يفسر بعضها بعضًا، ويشرح بعضها بعضًا. وهذا هو التوفيق بين النصوص: أن المرأة إذا شرطت مهرها أن يقدم لها فإنه يقدم، وهكذا لو شرطت بعضه يقدم ما شرطت، وما رضيت أنه يؤخر، يؤخر ولا حرج، حتى ولو كانت شرطت أنه يقدم إذا سمحت، وأجلته عليه، أو أسقطته عنه، فلا حرج، إذا كانت رشيدة لها أن تسقطه بالكلية، قال الله -جل وعلا- في كتابه الكريم: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] فإذا طابت نفسها بشيء من المهر، أو بكله فلا بأس على الزوج أن يأكله هنيئًا مريئًا، إذا كانت رشيدة، فهذا الشيء يرجع إلى المرأة، وأوليائها ينظرون في المرأة ............. فإذا رأت المرأة الرشيدة، أو أولياؤها تقديم المهر قدم، وإذا رأوا تأجيله أجل، وإذا رأوا تأجيل بعضه، وتعجيل بعضه فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/15856/حكم-الدخول-بالمراة-قبل-اعطاىها-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_721/nour_72110.mp3","categories":["الصداق"]},{"id":17070,"question":"سماحة الشيخ! هذه الأخت السائلة: (ح. م. ش) من الرياض تقول: هل في الحلي الملبوس للزينة زكاة؟ وإذا وقع خلاف بين العلماء حول مسألةٍ ما بأي قولٍ آخذ وأعمل؟ أفتونا بذلك مأجورين.","title":"حكم زكاة الحلي الملبوس","answer":"الجواب: الصواب أن فيها الزكاة، الحلي من الذهب والفضة فيها الزكاة، هذا الصواب، وبعض أهل العلم لا يرى فيها الزكاة، لكن الصواب أنه فيها الزكاة، إذا بلغت النصاب، وحال عليها الحول تزكي من الذهب، أو الفضة، ربع العشر، في المائة ريالين ونص، وللذهب إذا كان مائة جنيه جنيهًا ونصف، يعني ربع العشر، هذا هو الواجب، وهذا هو الصواب. وإذا اختلف العلماء فالواجب الأخذ بالدليل، الذي معه الدليل من القرآن، أو السنة هو الذي يجب اتباعه؛ لأن الله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59] فإذا تنازع العلماء في شيء فالواجب الرد إلى القرآن والسنة، وقد دلت السنة على أن الحلي فيها الزكاة، وقد بين النبي ﷺ أن الذهب فيه الزكاة والفضة فيها الزكاة، ورأى امرأةً عليها حلي، فقال: أتؤدين زكاتها؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ دل على وجوب الزكاة، ولما سألته أم سلمة عن حلي لها: «أهي كنزٌ؟ قال: إذا أديت زكاتها فليست بكنز. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15875/حكم-زكاة-الحلي-الملبوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58810.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":17176,"question":"هذا السائل مهدي محمد يقول: بأنه شاب، ويحب أن يتزوج ببنت، ولكن والد هذه البنت طلب منه مبالغ كبيرة، ودفعة واحدة، يقول: وأنا أحب هذه البنت، فكيف يكون الحل؟ وأطلب منكم الدعاء بأن يهدي الله  قلبي، ولكم جزيل الشكر.","title":"الحث على التسهيل في الزواج وترك التكلف","answer":"الجواب: يسر الله أمرك، وأمر كل مسلم، وهدى أباها حتى يسامحك بعض الشيء، والتسهيل في الزواج مهم، وعدم التكلف، إذا حصل الكفء؛ فالأفضل للولي، والمرأة عدم التكلف، وأن يرضوا بالشيء الميسور، وألا يتكلفوا في المهور، ولا في الولائم حتى يتيسر الزواج للرجال، والنساء جميعًا، هذا هو الأفضل. وإذا لم تستطع؛ فاصبر حتى يسهل الله الأمر، لقول النبي ﷺ: يا معشر الشباب، من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع؛ فعليه بالصوم، فإنه له وجاء والله يقول -جل وعلا-: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] ثم يقول بعده: وَلْيَسْتَعْفِفِ الَّذِينَ لا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِهِ [النور:33] يعني: الذي لا يجد عليه أن يستعف، يتصبر، ويتحمل حتى يغنيه الله. فالمقصود: أن المؤمن يسعى في النكاح، وأسبابه حسب طاقته، فإذا لم يتيسر ذلك صبر حتى يفرج الله الأمور. نعم.","link":"https://binbaz.org.sa/fatwas/15994/الحث-على-التسهيل-في-الزواج-وترك-التكلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59005.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":17372,"question":"سماحة الشيخ هذه سائلة من الرياض لها مجموعة من الأسئلة، تبدأ هذه الأسئلة بهذا السؤال وتقول: سماحة الشيخ! لدي مجموعة من الذهب المستعمل، وأردت أن أخرج عنه الزكاة، وعندما ذهبت لوزنه وجدته يزن تسعة وسبعين جرامًا تقريبًا أي: دون النصاب البالغ خمسة وثمانين جرامًا، ولكنني في نفس اليوم الذي وزنت فيه الذهب القديم اشتريت ذهبًا آخر يزن ثلاثة وعشرين جرامًا فأصبح مجموع وزن الذهب الجديد والقديم حوالي مائة واثنين جرامًا، والسؤال هو يا سماحة الشيخ: هل أضيف مجموع وزن الذهب الذي اشتريته مع وزن القديم، وأخرج عنه الزكاة، أم أنتظر حتى يحول الحول عليه على الذهب الجديد، فأخرج الزكاة عن هذا الذهب القديم، والجديد معًا؟ أفيدوني مأجورين.","title":"شروط وجوب الزكاة في الذهب","answer":"الجواب: نعم ليس عليك زكاة في الحول الحاضر، ولكن بعد ضم الجديد إلى القديم إذا حال الحول تزكينه، أما قبل ذلك فلا؛ لأنه ناقص، لكن بعد ما يحول الحول على الجديد، والقديم تزكين والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16233/شروط-وجوب-الزكاة-في-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77010.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":17465,"question":"يسأل أخونا سؤاله الثاني، فيقول: بالنسبة لزينة المرأة من الذهب، هل لها مقدار معين، وإذا كانت ذات وزن كبير مثلًا، فكيف تكون الزكاة؟ جزاكم الله خيرًا.","title":"هل لحلي المرأة مقدار معين؟ وحكم زكاته","answer":"الجواب: ليس للحلي للمرأة مقدار معين فيما نعلم، بل لا بأس أن تتزين بما يسر الله لها من الزينة من الأساور، والقلائد، والخواتم ونحو ذلك، وإذا بلغت هذه الزينة من الذهب النصاب عشرين مثقالًا، يعني: أحد عشر جنيهًا ونصف بالجنيه السعودي، وبالغرام اثنان وتسعين غرامًا، متى بلغت النصاب هذا وجب عليها الزكاة في أصح قولي العلماء، أنها تزكي في الألف خمسة وعشرون، يعني ربع العشر، هذا هو الصواب. وقال بعض أهل العلم: إن الحلي ليس فيها زكاة، والصواب أن فيها الزكاة؛ لأنه ورد في ذلك أحاديث صحيحة صريحة تدل على ذلك، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16333/هل-لحلي-المراة-مقدار-معين-وحكم-زكاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72502.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":17590,"question":"يسأل يقول: هل يجوز للشخص أن يتزوج من مهر أخته؟","title":"حكم زواج الأخ بمهر أخته","answer":"الجواب: إذا سمحت له أخته، إذا أعطته من مهرها وهي مكلفة رشيدة وأعطته من مهرها ما يتزوج به فلا بأس، هذا من باب التعاون على البر والتقوى، من باب صلة الرحم، فإذا كانت أخته رشيدة أو عمته رشيدة أو خالته وأعطته مالًا يتزوج به هذا معروف، وهذا من باب صلة الرحم ولا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16528/حكم-زواج-الاخ-بمهر-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84113.mp3","categories":["الصداق"]},{"id":17929,"question":"تسأل سؤال تقول فيه: ما رأي سماحتكم في المغالاة في المهور، وما هو المهر الشرعي للمرأة في الإسلام؟","title":"هل للمهر حد محدد؟","answer":"الجواب: ليس للمهر حد محدود ولكن الأفضل عدم المغالاة، الأفضل للمسلمين أن لا يغالوا ولا يتكلفوا حتى يكثر الزواج وتقل العزوبة ومتى غالى الناس في المهور وتكاليف الزواج تعطل الكثير من الشباب والنساء، فالسنة التخفيف كما في الحديث خير الصداق أيسره، والنبي ﷺ قال لبعض الناس لما قال: ما عنده شيء، قال: التمس ولو خاتمًا من حديد، وزوج بعض الناس بتعليم القرآن وتعليم سور من القرآن فالأمر في هذا واسع.\nفالسنة للمسلمين أن لا يغالوا وألا يتكلفوا حتى يسهلوا الزواج للراغبين في الزواج. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16949/هل-للمهر-حد-محدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84702.mp3","categories":["الصداق"]},{"id":18590,"question":"أخونا له سؤال آخر يقول: كان -وإلى عهد قريب جدًّا- يتم عقد الزواج عندنا باثنين جنيه، والآن أصبح بخمسين جنيهًا سودانيًا، مما سبب بعض المشكلات الاجتماعية لدى الكثير من المسلمين الذين لم يقتنعوا بالزيادة الأخيرة، فمنهم من أصر على العقد بالجنيهين، وتزوج بها، ومنهم من تزوج بالخمسين جنيهًا، وقد اعتبر من تزوج بالجنيهين زواجه باطلًا، يدخل في حرمة الزنا، وكل ذلك مرد تفسيره لاعتبارات انخفاض القيمة للجنيه السوداني في الآونة الأخيرة، فكما تعلمون أن العملات قابلة للانخفاض والارتفاع على حسب الحالة الاقتصادية لدى الدول.فبماذا تنصحون وترشدون أولئك المأذونين الذين يصرون على دفع الخمسين جنيهًا؟ ليتم على أيديهم العقد الصحيح -كما يقولون- وإلا أنهم سوف لن يتحملوا تنفيذ إجراءات العقد، وقد فعل بعضهم وامتنع بالفعل، ثم ماذا يا صاحب السماحة عن الزواج بالفاتحة أو بشيء من القرآن في زماننا هذا، هل يجوز أم لا؟أجيبونا أثابكم الله.","title":"حكم تحديد المهر","answer":"الجواب: ليس للمهر حد محدود في الشرع، بل يجوز أن يكون قليلًا وكثيرًا؛ لأن الله قال: أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24] ولم يحدد، والرسول ﷺ لم يحدد؛ ولهذا ذهب جمهور أهل العلم إلى أنه لا حد لأقله ولا حد لأكثره، فما تراضى عليه الزوجان وولي الزوجة كفى ولو قليلًا. وإذا تحدد المهر في قبيلة أو طائفة من الناس، أو في قرية من القرى؛ فينبغي للزوج أن يلتزم بذلك حتى لا تقع المنازعات والخصومات، وإذا سامحته بعد ذلك زوجته، وأسقطت عنه بعض المهر فلا بأس؛ لأن الله يقول سبحانه: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا [النساء:4] فيلتزم بما قرره جماعته؛ حتى لا يقع النزاع بينه وبينهم، ويتفقون مع أهلها أو وليها أنهم سيسامحونه فيما يشق عليه في المستقبل، فإن لم يتيسر ذلك أعانه الله، هذا طريق ينبغي فيه الصبر والتحمل؛ لما فيه من العفة للفرج وإحصانه، وغض البصر، والتسبب في وجود الذرية الصالحة، ينبغي له أن يتحمل. ولو اتفقوا على مهر قليل؛ صح النكاح، ولم يبطل النكاح، ولو خالف المقرر، لكن لا ينبغي أن يخالف المقرر؛ لأنه يحصل بذلك تشويش، ونزاع بينه وبين جماعته، وربما أفضى إلى شر كثير، فينبغي له أن يلتزم، ثم يطلب من زوجته المسامحة بعد ذلك أو وليها أو من كليهما، أن يسامحوه أو يساعدوه فيما شق عليه من ذلك، وهذا شيء بينهم، داخليًا لا يتعلق بالخارج، الخارج إنما هو الالتزام بالمهر المقرر حتى لا تقع المنازعات والخصومات والأذى، وفي إمكانه بعد ذلك أن يقبل من زوجته وأهلها ما سمحوا عنه، نعم.","link":"https://binbaz.org.sa/fatwas/17721/حكم-تحديد-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_871/nour_87102.mp3","categories":["الصداق"]},{"id":18642,"question":"رسالة وصلت إلى البرنامج من المستمع: محمد حلمي ميرة العجوزة مصر، أخونا رسالته مطولة بعض الشيء يقول فيها: تقدمت لخطبة ابنة إحدى الأسر، وبعد القبول من الطرفين قرأنا الفاتحة بحضور أسرتينا، بعدها بأيام سافرت للعمل بإحدى الدول العربية، ثم عدت في إجازة بعد ستة أشهر، وتم خلالها الاتفاق على تحديد قيمة الشبكة والمهر الذي سيدفع، وتم عمل حفل الخطوبة، ثم اشترينا الشقة -بيتنا الجديد- وتم الاتفاق كذلك على أن يكون حفل الزفاف مع نهاية تعاقدي الذي سيحل بعد انقضاء خمسة شهور، وتهيأت للسفر لاستكمال بقية المدة، وقبل يومين من السفر طلب والد خطيبتي أن أدفع له المهر الذي اتفقنا عليه سلفًا؛ حتى يمكن من إجراء التجهيزات وشراء الأثاث لبيتنا الجديد، ولكني رفضت ذلك، وقلت له: أنا لن أدفع المهر إلا مع عقد القران، لكنه استنكر ذلك، وقال: المتبع لدينا هو عقد القران مع ليلة الزفاف، تجادلنا طويلًا، وقال: سل ذوي التجارب ممن سبقوك إلى دنيا الزواج، ستجد موقفي هو الصواب، وعمومًا إذا لم يكن لديك مال الآن يمكن أن أدفعه، ثم تسدده فيما بعد، وبدوري أتساءل: هل يمكن دفع المهر في أي وقت دونما الارتباط بعقد القران؟ أم هو مرتبط به؟ وهل يعقد القران أولًا ثم يدفع المهر فيما بعد؟وجهوني جزاكم الله خيرًا.","title":"متى يُدفع المهر؟","answer":"الجواب: هذه مسائل عرفية، يجوز أن يدفع المهر قبل العقد، ويجوز حين العقد، ويجوز بعد العقد، المهم أن يتفقا عليه في صلب العقد، فإذا اتفقا على شيء وجب على الزوج تسليمه، فإن اتفقوا عليه حالًا وجب تسليمه حالًا، وإن اتفقوا عليه مؤجلًا وجب تسليمه عند أجله، وإن قدمه قبل العقد كما هي عادة كثير من الناس يقدمونه قبل العقد حتى يتمكن أهل الزوجة من التجهيزات اللازمة فهذا كافٍ، ولا يحتاج إلى تحديد شيء، بل متى أعطاهم ما تيسر ورضوا به كفى، وإن لم يتفق أنهم حددوا شيئًا، والناس بهذا يختلفون، فمن قدم شيئًا مما طابت به نفسه إلى أهل الزوجة، ورضوا به، ولم يردوه كفى، أما إن حددوه بشيء فهو مخير، إن شاء سلم لهم محدد، وإن شاء ترك الخطوبة منهم والزواج منهم، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17755/متى-يدفع-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91903.mp3","categories":["الصداق"]},{"id":19386,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. م. ع) يسأل ويقول: هل يجب أن يقبض صداق المرأة عند تسميته أو عند العقد؟ أم تكفي تسميته ويجوز تأجيله إلى وقت لاحق بعد الزواج؟ جزاكم الله خيرًا.","title":"حكم تعجيل المهر وتأجيله","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه وأتباعه بإحسان. أما بعد:\nفهذه المسألة ترجع إلى اتفاق الزوجين أو الزوج وولي المرأة، إذا اتفقا على شيء فلا بأس، تعجيل أو تأجيل أو تعجيل بعض وتأجيل بعض، كل ذلك واسع والحمد لله؛ لقوله ﷺ: المسلمون على شروطهم، ويقول ﷺ: إن أحق الشروط أن يوفى به ما استحللتم به الفروج. فإذا اتفقا على أن المهر يقدم أو أنه يؤخر، أو يقدم بعض ويؤخر بعض، كل ذلك لا بأس به، لكن السنة أن يسمى شيء عند العقد؛ لقوله تعالى: أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ [النساء:24]، فيسمي شيئًا من المهر، إذا سمى شيئًا فهو حسن، وإن قال: على مهر مؤجل ولم يسمياه فلا بأس، مؤجل إلى كذا أو مؤجل نصفه أو ثلثه أو ربعه، ويبين المعجل والمؤجل؛ لا بأس كله واسع والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18607/حكم-تعجيل-المهر-وتاجيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74001.mp3","categories":["الصداق"]}]
